Medic.internal.newLifeQuestFixTranslations = {
    ["Stirk Fellowship Soldier^m"] = "Soldat der Stirk-Gefolgschaft^m",
    ["Stirk Fellowship Mage^f"] = "Magierin der Stirk-Gefolgschaft^f",
    ["Coldharbour Void-Shade^f"] = "Kalthafen-Leerenschatten^fm",
    ["Statue^m"] = "Statue^mf",
    ["\"There is no such thing as too much, sahida. Not in fashion. This could have been simple, plain, fit for a common fighter. Yes. But in the claws of Fazudah it became so much more!\"—Fazudah"] = "„So etwas wie ‚zu viel‘ gibt es gar nicht, Sahida. Nicht bei Kleidung. Das hätte etwas Einfaches, Simples, für einen gewöhnlichen Kämpfer sein können. Ja. Aber in den Krallen von Fazudah wurde es so viel mehr!“ – Fazudah",
    ["Applies to Mages' Fury, Endless Fury, and Mages' Wrath. Select in Skills menu."] = "Wird auf „Magierzorn“, „endloser Zorn“ und „Magierrage“ angewendet. Im Fertigkeitenmenü auswählen.",
    ["Applies to Dark Exchange, Dark Conversion, and Dark Deal. Select in Skills menu."] = "Wird auf „dunkler Austausch“, „dunkle Umwandlung“ und „dunkles Abkommen“ angewendet. Im Fertigkeitenmenü auswählen.",
    ["Applies to Siphoning Strikes, Leeching Strikes, and Siphoning Attacks. Select in Skills menu."] = "Wird auf „auslaugende Schläge“, „entziehende Angriffe“ und „auslaugende Angriffe“ angewendet. Im Fertigkeitenmenü auswählen.",
    ["Applies to Strife, Funnel Health, and Swallow Soul. Select in Skills menu."] = "Wird auf „Unfriede“, „Lebensfluss“ und „Seelenschlingen“ angewendet. Im Fertigkeitenmenü auswählen.",
    ["Magma Armor, Azure Blue"] = "Magmarüstung, Azurblau^f",
    ["Applies to Magma Armor, Corrosive Armor, and Magma Shell. Select in Skills menu."] = "Wird auf „Magmarüstung“, „korrosive Rüstung“ und „Magmaschale“ angewendet. Im Fertigkeitenmenü auswählen.",
    ["Molten Weapons, Azure Blue"] = "geschmolzene Waffen, Azurblau^p",
    ["Applies to Molten Weapons, Igneous Weapons, and Molten Armaments. Select in Skills menu."] = "Wird auf „geschmolzene Waffen“, „eruptive Waffen“ und „geschmolzenes Arsenal“ angewendet. Im Fertigkeitenmenü auswählen.",
    ["Applies to Arrow Spray, Acid Spray, and Bombard. Select in Skills menu."] = "Wird auf „Pfeilfächer“, „Säurefächer“ und „Bombarde“ angewendet. Im Fertigkeitenmenü auswählen.",
    ["Applies to Twin Slashes, Blood Craze, and Rending Slashes. Select in Skills menu."] = "Wird auf „Doppelschnitte“, „Blutwahn“ und „Trennschnitte“ angewendet. Im Fertigkeitenmenü auswählen.",
    ["Dummy Demolisher"] = "Übungspuppen-Zerstrümmerung^f",
    ["Crate Topper, Moons Over Orsinium"] = "Kistenabdeckung, Monde über Orsinium",
    ["Applies to Healing Seed, Budding Seeds, and Corrupting Pollen. Select in Skills menu."] = "Wird auf „heilende Saat“, „sprießende Saat“ und „verderbende Pollen“ angewendet. Im Fertigkeitenmenü auswählen.",
    ["Applies to Cleansing Ritual, Extended Ritual, and Ritual of Retribution. Select in Skills menu."] = "Wird auf „reinigendes Ritual“, „verlängertes Ritual“ und „Ritual der Vergeltung“ angewendet. Im Fertigkeitenmenü auswählen.",
    ["Applies to Grim Focus, Merciless Resolve, and Relentless Focus. Select in Skills menu."] = "Wird auf „grimmiger Fokus“, „gnadenlose Entschlossenheit“ und „unermüdlicher Fokus“ angewendet. Im Fertigkeitenmenü auswählen.",
    ["Applies to Frost Cloak, Expansive Frost Cloak, and Ice Fortress. Select in Skills menu."] = "Wird auf „Frostmantel“, „weiter Frostmantel“ und „Eisbollwerk“ angewendet. Im Fertigkeitenmenü auswählen.",
    ["Applies to Fatecarver, Exhausting Fatecarver, and Pragmatic Fatecarver. Select in Skills menu."] = "Wird auf „Schicksalsschnitzer“, „erschöpfender Schicksalsschnitzer“ und „pragmatischer Schicksalsschnitzer“ angewendet. Im Fertigkeitenmenü auswählen.",
    ["Applies to Snipe, Focused Aim, and Lethal Arrow. Select in Skills menu."] = "Wird auf „Präzisionsschuss“, „gezielter Schuss“ und „tödlicher Pfeil“ angewendet. Im Fertigkeitenmenü auswählen.",
    ["Applies to Radiant Destruction, Radiant Glory, and Radiant Oppression. Select in Skills menu."] = "Wird auf „strahlende Zerstörung“, „strahlender Ruhm“ und „strahlende Unterdrückung“ angewendet. Im Fertigkeitenmenü auswählen.",
    ["Applies to Puncturing Strikes, Biting Jabs, and Puncturing Sweep. Select in Skills menu."] = "Wird auf „durchschlagende Hiebe“, „harsche Hiebe“ und „durchschlagender Schwung“ angewendet. Im Fertigkeitenmenü auswählen.",
    ["Applies to Bone Armor, Beckoning Armor, and Summoner's Armor. Select in Skills menu."] = "Wird auf „Knochenrüstung“, „heranrufende Rüstung“ und „Rüstung des Beschwörers“ angewendet. Im Fertigkeitenmenü auswählen.",
    ["Applies to Render Flesh, Blood Sacrifice, and Resistant Flesh. Select in Skills menu."] = "Wird auf „Fleisch formen“, „Blutopfer“ und „resistentes Fleisch“ angewendet. Im Fertigkeitenmenü auswählen.",
    ["Applies to Abyssal Impact, Cephaliarch's Flail, and Tentacular Dread. Select in Skills menu."] = "Wird auf „abgründiger Einschlag“, „Flegel des Kephaliarchen“ und „Tentakelschrecken“ angewendet. Im Fertigkeitenmenü auswählen.",
    ["Applies to Runespite Ward, Impervious Runeward, and Spiteward of the Lucid Mind. Select in Skills menu."] = "Wird auf „Runentrotzschutz“, „undurchdringlicher Runenschutz“ und „Geisterschutz des brillanten Verstands“ angewendet. Im Fertigkeitenmenü auswählen.",
    ["Applies to Soul Trap, Consuming Trap, and Soul-Splitting Trap. Select in Skills menu."] = "Wird auf „Seelenfalle“, „erholende Seelenfalle“ und „trennende Seelenfalle“ angewendet. Im Fertigkeitenmenü auswählen.",
    ["A small clay statuette in the shape of a bat, painted with red polish.\n\nThe first of three components required to create the Roseblood Bat."] = "Eine kleine Lehmstatue in Gestalt einer Fledermaus, die rotglänzend bemalt wurde.\n\nDie erste von drei Komponenten für die Rosenblut-Fledermaus.",
    ["Petals that fall from Sanguine's prized roses are not known to wilt, and are always slightly damp with blood.\n\nThe second of three components required to create the Roseblood Bat."] = "Blütenblätter, die von Sanguines kostbaren Rosen fallen, verwelken bekanntermaßen nicht und sind immer leicht mit Blut benetzt.\n\nDie zweite von drei Komponenten für die Rosenblut-Fledermaus.",
    ["A deadly-sharp rose thorn from one of the myriad rosebushes that grow in Sanguine's eternal paradise. Watch your finger!\n\nThe last of three components required to create the Roseblood Bat."] = "Ein tödlich spitzer Rosendorn von einem der unzähligen Rosensträucher, die in Sanguines ewigem Paradies gedeihen. Passt auf Eure Finger auf!\n\nDie letzte von drei Komponenten für die Rosenblut-Fledermaus.",
    ["In the halls of the Daedra, their crude mockeries of Tamrielic traditions extend to the courtesies of courtly dancing as well.\n\nA component required for the Roseblood Wings Recall customized action."] = "In den Hallen der Daedra erstreckt sich ihre grobe Verhöhnung der Traditionen Tamriels auch auf die Höflichkeitsformen des höfischen Tanzes.\n\nEine Komponente für den Rückruf der Rosenblut-Schwingen als angepasste Aktion.",
    ["Darkly beautiful and ringed with bloody thorns, this fashionable accoutrement lures in dance partners while also pricking those who get too close.\n\nA component required for the Roseblood Wings Recall customized action."] = "Von düsterer Schönheit und umringt von blutigen Dornen, lockt dieses modische Accessoire Tanzpartner an und sticht gleichzeitig diejenigen, die zu nahe kommen.\n\nEine Komponente für den Rückruf der Rosenblut-Schwingen als angepasste Aktion.",
    ["Victims of this deadly poison are found with reddened lips; the mark of one last dalliance with forbidden romance.\n\nA component required for the Roseblood Wings Recall customized action."] = "Opfer dieses tödlichen Gifts findet man mit erröteten Lippen – dem Zeichen einer letzten Tändelei mit einer verbotener Romanze.\n\nEine Komponente für den Rückruf der Rosenblut-Schwingen als angepasste Aktion.",
    ["Wardrobe,Costume,Wardrobe,Disguise,Covering,Clothes,Gear,Wear,Worn,Apparel"] = "Garderobe, Kostüm, Garderobe, Verkleidung, Deckung, Kleidung, Ausrüstung, abgenutzt, Mode",
    ["Go on with Jeetra. These death-dancers seem to be quite capable! I'm not sure I totally trust the name, though.\n\nAnd don't worry about me. I'll be fine. Just need to clear my head. And … thanks for earlier. Gave me a lot to think about."] = "Geht ruhig mit Jeetra. Diese Todestänzer wirken recht wacker! Ich bin mir nicht sicher, ob der Name wirklich mein Vertrauen weckt.\n\nUnd macht Euch um mich keine Sorgen. Ich komme zurecht. Ich muss einfach nur einen klaren Kopf bekommen. Und ... habt Dank für vorhin. Das gab mir eine Menge zum Nachdenken.",
    ["I have to ask—was it fun being a giant statue and stepping on cultists? Because it looked like fun from where I was standing.\n\nAnyway, now that we're here, what's next?"] = "Ich muss einfach fragen: Hat es Spaß gemacht, eine riesige Statue zu sein und auf Kultisten zu treten? Denn es sah von meiner Warte nach Spaß aus.\n\nAber jetzt, da wir hier sind, was kommt als Nächstes?",
    ["What a waste, and all because a lector got greedy. We can rebuild the lodge, but the lives lost … those are gone forever.\n\nStill, it would have been worse if you hadn't shown up. Thanks."] = "Was für eine Verschwendung und alles nur, weil eine Lektorin gierig wurde. Wir können die Residenz wieder aufbauen, aber die verlorenen Leben ... sie sind für immer fort.\n\nDoch es hätte schlimmer kommen können, wenn Ihr nicht aufgetaucht wärt. Danke.",
    ["Latanwen took a fire bolt meant for me. If I can't get her out of here, I'll never forgive myself.\n\nBut who are you, stranger? You don't look like a cultist, and you're certainly not part of the college. What are you doing here?"] = "Latanwen fing einen Feuerstoß ab, der für mich bestimmt war. Wenn ich sie hier nicht rausbringen kann, werde ich mir das nie verzeihen.\n\nAber wer seid Ihr, <<player{Fremder/Fremde}>>? Ihr seht nicht nach <<player{einem Kultisten/einer Kultistin}>> aus und Ihr gehört sicher nicht zum Kolleg. Was macht Ihr hier?",
    ["May the Ancient Darkness guide your travels, friend. Perhaps I will see you again some dark night. I jest, I jest. I am a morning person.\n\nFeel free to examine my work. The ancient words of the death-dancers are fascinating!"] = "Möge die Uralte Finsternis Euch auf Euren Reisen leiten, <<player{Freund/Freundin}>>. Vielleicht sehe ich Euch ja eines düsteren Abends wieder. Keine Sorge, ich scherze nur. Ich bevorzuge den Morgen.\n\nSeht Euch gern mein Werk an. Die uralten Worte der Todestänzer sind faszinierend!",
    ["Go get those components for the siege weapon, long-strider.\n\nOr do what Argie says. Suraj isn't your captain. Figure it out yourself! I'm trying to catch some fish. Someone's got to make sure this crew gets fed."] = "Holt Euch die Komponenten der Belagerungswaffe, Langschritt.\n\nOder tut, was Argie sagt. Suraj ist nicht Euer Kapitän. Entscheidet selbst! Ich werde ein paar Fische fangen gehen. Irgendjemand muss ja dafür sorgen, dass die Mannschaft nicht hungert.",
    ["Captain ordered me to stay here and protect the surviving crew.\n\nI would rather be out there doing what you're doing, but orders are orders."] = "Der Kapitän befahl mir, hier zu bleiben und die Überlebenden zu beschützen.\n\nIch wäre lieber draußen bei Euch dabei. Aber Befehl ist Befehl.",
    ["Don't mind Kauldin. Lector Fenworine's betrayal stung him like an angry netch. And after I was wounded and another apprentice fell, he's been extremely cautious.\n\nBut if you aren't with the Worm Cult, who are you?"] = "Achtet nicht auf Kauldin. Lektorin Fenworines Verrat schmerzt ihn mehr als ein wütender Netch. Und nachdem ich verwundet wurde und ein anderer Lehrling fiel, ist er extrem vorsichtig.\n\nAber wenn Ihr nicht zum Wurmkult gehört, wer seid Ihr?",
    ["Suraj said he wished we met you before all this. Thinks things would have been different for all of us.\n\nMaybe so. But I've never been one to look back in such a way. Makes my neck hurt."] = "Suraj wünschte, wir hätten Euch vor all dem schon gehabt. Dann wäre alles anders gekommen.\n\nAber auch wenn dem so sein mag: Ich bin niemand, der zurückblickt. Verrenkt einem nur den Hals.",
    ["Fine job rousing those mutineers. Desa got here just before you. Quite the spitfire, isn't she? So long as she doesn't eat any of the others, or make a habit of mutiny, she'll make a fine addition to the crew.\n\nWell, are you ready?"] = "Ihr habt diese Meuterer ja prächtig aufgewiegelt. Desa kam kurz vor Euch an. Ein echter Hitzkopf, nicht wahr? Solange sie keinen der anderen auffrisst oder nun ihre Leidenschaft für Meuterei entdeckt hat, wird sie die Mannschaft prächtig ergänzen.\n\nAlso, seid Ihr bereit?",
    ["Suraj, you've met already. Argenta … requires a bit more patience. Which is why I asked you to speak to her first.\n\nGot no soul, but she's still got a good heart."] = "Suraj kennt Ihr ja schon. Argenta ... erfordert ein wenig mehr Geduld. Deswegen bat ich Euch, zuerst mit ihr zu sprechen.\n\nSie hat keine Seele, wohl aber ein gutes Herz.",
    ["I will aid you if I can, but this fight belongs to you and Darien. The rest of us cannot touch Mannimarco without the Light of Meridia to strengthen our blows."] = "Ich werde Euch helfen, so gut ich kann, aber ich fürchte, dass dieser Kampf Euch und Darien gehört. Der Rest von uns kann Mannimarco nichts tun, ohne dass ein Licht von Meridia unsere Schläge stärkt.",
    ["Those blighting cultists and their Daedra took my sister, Lienyl. We were so close to getting away! She wanted to start a new life outside of Coldharbour.\n\nInstead, we just landed in another nightmare."] = "Diese vermaledeiten Kultisten und ihre Daedra haben meine Schwester Lienyl entführt. Um ein Haar wären wir entkommen! Sie wollte ein neues Leben fernab von Kalthafen anfangen.\n\nStattdessen landeten wir im nächsten Albtraum.",
    ["With all the Daedra, I did not expect to find Tindensea is still here. Perhaps she can help us find the old manuscripts Elder Tso-Nassa spoke of. I would hate to have to search through all these shelves without some guidance."] = "Ob all der Daedra dachte ich nicht, dass wir Tindensea noch hier vorfinden würden. Vielleicht kann sie uns helfen, die alten Manuskripte aufzuspüren, von denen der Älteste Tso-Nassa sprach. Ich hasse den Gedanken, all diese Regale ohne Hinweise durchgehen zu müssen.",
    ["If you're done talking Darien out of his dark mood, I'm eager to hear your report. Jeetra explained about Vanus's note in the mine, but what happened at the soul flayer harvest sites? Skordo and Raz said you destroyed them, but not much else."] = "Falls Ihr fertig seid, Darien mit Euren Gesprächen aus seiner düsteren Stimmung herauszuhelfen, bin ich gespannt, Euren Bericht zu hören. Jeetra erklärte mir alles, was die Notiz von Vanus in der Mine angeht. Doch was geschah an den Erntestätten für die Seelenschinder? Skordo und Raz sagten, Ihr hättet sie zerstört, aber sonst nicht viel.",
    ["Captain One-Eye said you mean to give a speech. Didn't have those back at the Caterwaul. Curious what you have to say."] = "Kapitän Ein-Auge sagte, dass Ihr eine Ansprache halten wollt. So etwas hatten wir auf der Gejaule nicht. Bin gespannt, was Ihr uns zu sagen habt.",
    ["That's all I have to give to you! At least let me finish the job before I head back to Sunport and turn myself in. I do have a reputation to uphold."] = "Mehr kann ich nicht geben! Lasst mich zumindest die Sache hier zu Ende bringen, bevor wir zurück nach Sonnhafen gehen und ich mich stelle. Ich muss an meinen Ruf denken.",
    ["You get one warning, stranger. I bite. And if you stick around too long, Captain Velehk Sain will take you prisoner and make a meal out of your soul.\n\nNow, get lost before I decide to eat you first."] = "Ich warne Euch nur einmal, <<player{Fremder/Fremde}>>: Ich beiße. Und wenn Ihr zu lange bleibt, wird Kapitän Velehk Sain Euch genfangen nehmen und sich an Eurer Seele laben.\n\nAlso verschwindet, bevor ich mich entschließe, Euch vorher aufzufressen.",
    ["That observer is on high alert. Someone must have seen you on your way here and raised the alarm.\n\nI just want to get out. If I'd known Captain Sain treats his crew as well as he treats his prisoners, I'd have just stayed a prisoner."] = "Der Beobachter ist angespannt. Jemand muss Euch auf dem Weg hierher gesehen und Alarm geschlagen haben.\n\nIch will hier nur raus. Hätte ich gewusst, dass Kapitän Sain seine Mannschaft so behandelt wie seine Gefangenen, wäre ich einfach Gefangene geblieben.",
    ["Seems like that observer has no idea you're here. You'd lose that advantage if one of us goes with you.\n\nI just want to get out. If I'd known Captain Sain treats his crew as well as he treats his prisoners, I'd have just stayed a prisoner."] = "Offenbar ahnt der Beobachter nicht, dass Ihr hier seid. Den Vorteil verliert Ihr, wenn einer von uns Euch begleitet.\n\nIch will hier nur raus. Hätte ich gewusst, dass Kapitän Sain seine Mannschaft so behandelt wie seine Gefangenen, wäre ich einfach Gefangene geblieben.",
    ["I am astonished. Ghadaz hasn't performed that well in years. I should start writing letters. People need to see this play."] = "Ich bin verblüfft. Ghadaz war seit Jahren nicht mehr so gut. Ich muss Briefe schreiben. Die Leute müssen dieses Stück sehen.",
    ["Let's leave this horrible place of torment and blood so Terinvel and I can calm down. We can talk back at my campsite."] = "Verlassen wir diesen grauenhaften Ort der Folter und des Blutes, damit Terinvel und ich uns beruhigen können. Wir sprechen in meinem Lager.",
    ["I was enjoying this batch, but as it says in the Tenets of the Black Worm, there's more victims where those came from.\n\nDark Adept Vairisse's rounds usually take her to the other side of that door about this time. You shouldn't keep her waiting."] = "Ich hatte meinen Spaß mit dieser Ladung, aber wie steht es in den Schriften des Schwarzen Wurms? „Wo diese Opfer herkommen, gibt es noch mehr.“\n\nFür gewöhnlich kommt die Dunkle Adeptin Vairisse auf ihrer Runde ungefähr jetzt an unserer Tür vorbei. Ihr solltet sie nicht warten lassen.",
    ["Traveler! Do not attack Sharadak! This one has captured the vile illusionist, Milie Reynaud, after chasing her across land and sea.\n\nShe is a very dangerous prisoner. If Sharadak is not careful, he may fall prey to another one of her vile tricks!"] = "<<player{Reisender/Reisende}>>! Greift Sharadak nicht an! Dieser hat die bösartige Illusionistin Milie Reynaud nach einer Jagd über Land und Meer ergriffen.\n\nSie ist eine sehr gefährliche Gefangene. Wenn Sharadak nicht aufpasst, wird dieser wieder Opfer einer ihrer fiesen Tricks.",
    ["Traveler! Sharadak seeks a bounty for the vile illusionist, Milie Reynaud. She is a master of disguise. This one has chased her across land and sea.\n\nIf this one is not careful, he may fall prey to another one of her devious tricks."] = "<<player{Reisender/Reisende}>>! Sharadak verlangt es nach dem Kopfgeld für die bösartige Illusionistin Milie Reynaud. Sie ist eine Meisterin der Verkleidung. Dieser hat sie über Land und Meer gejagt.\n\nWenn dieser nicht aufpasst, wird er wieder Opfer einer ihrer arglistigen Tricks.",
    ["You're not from in the Hall. I would recognize you. Which means you broke in somehow. Maybe through the rumored breaches in the walls?\n\nDon't fear that I'll hurt you, mortal. I just want to find a way out. I can't survive in this place."] = "Ihr kommt nicht aus der Halle. Ich hätte Euch erkannt. Also seid Ihr irgendwie eingebrochen. Vielleicht durch die Durchbrüche in der Wand, von denen ich hörte?\n\nKeine Angst, ich tue Euch nichts, <<player{Sterblicher/Sterbliche}>>. Ich suche nur einen Weg nach draußen. Ich kann an diesem Ort nicht überleben.",
    ["Of all the times for that silly hound to try to be a hero.\n\nNever realized how much I actually care about him."] = "Musste dieser alberne Hund ausgerechnet jetzt den Helden spielen?\n\nMir war nie klar, wie sehr er mir tatsächlich ans Herz gewachsen ist.",
    ["Traveler! You are not with the Worm Cult, are you? I beg a moment of your time. I need someone to deliver a message to Healer Namreras at the Central Siege Camp.\n\nI need you to tell her that her husband, Tesamoril is … dead."] = "<<player{Reisender/Reisende}>>! Ihr gehört nicht zum Wurmkult, oder? Ich erflehe einen Augenblick Eurer Zeit. Ich brauche jemanden, der Heilerin Namreras im zentralen Belagerungsposten eine Nachricht überbringt.\n\nIhr müsst ihr sagen, dass ihr Ehemann Tesamoril ... tot ist.",
    ["Dark Adept Vairisse is a stern commander who does not like to be kept waiting. Which is why we should probably have been faster extracting those souls."] = "Die Dunkle Adeptin Vairisse ist eine strenge Kommandantin, die nur ungern wartet. Deshalb sollten wir uns vermutlich beeilen mit dem Extrahieren dieser Seelen.",
    ["Is it me or has Skordo gotten worse at holding his liquor?\n\nAnd you! Sit, sit. This has been a long time coming. I've promised you more drinks than I can count. Not sure I can afford to make good on all of them, but let's give it a try!"] = "Bin das nur ich oder kann Skordo nicht mehr soviel vertragen?\n\nUnd Ihr? Setzt Euch, setzt euch. Wir mussten lange darauf warten. Ich habe öfter versprochen, mit Euch einen zu heben, als ich zählen kann. Ich bin nicht sicher, ob ich es mir leisten kann, wenn Ihr das alles einlöst, aber wir wollen es versuchen!",
    ["I must return to the mainland and report all we've uncovered here. Just one more task to add to my already overburdened schedule.\n\nSolstice has been … eventful. I'd welcome a little peace, but peace rarely lingers for those such as us, doesn't it?"] = "Ich muss zum Festland zurück und alles melden, was wir hier entdeckt haben. Eine weitere Aufgabe für meinen übervollen Terminplan.\n\nSonnenwende war ... ereignisreich. Mir wäre ein wenig Frieden recht, aber Frieden hält nie lange an für solche wie uns, nicht wahr?",
    ["Oh, thank you so much! I would have been heartbroken if they didn't get something for New Life. Now, allow me to offer you my gratitude. I hope this helps you on your journeys ahead.\n\nReturn soon and we'll make another meal to offer for New Life!"] = "Oh, vielen Dank! Es hätte mir das Herz gebrochen, wenn sie zum Neujahrsfest nichts bekommen hätten. Lasst mich mich erkenntlich zeigen. Ich hoffe, dies hilft Euch auf Euren bevorstehenden Reisen.\n\nKehrt bald zurück, damit wir mehr Speisen zubereiten und zum Neujahrsfest anbieten können.",
    ["Talk to Lanullin"] = "Sprecht mit Lanullin",
    ["I prepared the offering and delivered it to the elder."] = "Ich habe die Ältesten-Gabe zubereitet und überbracht.",
    ["Then Tibarr proclaims this New Life a success! Allow this one to reward you for your noble efforts. It's the least Tibarr can do for enduring his silly festivity.\n\nAnd Tibarr promises more if you brave his Dragon's lair again!"] = "Dann verbucht Tibarr das Neujahrsfest als Erfolg! Erlaubt diesem, Euch für Eure edlen Taten zu belohnen. Das ist das Mindeste, was Tibarr dafür tun kann, dass Ihr seine albernen Festspiele ertragen habt.\n\nUnd Tibarr verspricht Euch mehr davon, falls Ihr Euch dem Drachenversteck erneut stellt!",
    ["Talk to Tibarr"] = "Sprecht mit Tibarr",
    ["I gave the Dragon's coin to Yarg."] = "Ich gab Yarg die Münze des Drachen.",
    ["Not bad, traveler. Seeking help is usually a last resort for me, but perhaps I've been too hasty to try to accomplish everything by myself.\n\nThere's still more New Life to celebrate, so feel free to swing by the next time you wander this way."] = "Nicht schlecht, <<player{Reisender/Reisende}>>. Hilfe anderer in Anspruch zu nehmen, ist für mich normalerweise das allerletzte Mittel, doch vielleicht war es zu vorschnell von mir, zu versuchen, alles allein hinzubekommen.\n\nDas Neujahrsfest geht noch weiter, also schaut ruhig wieder vorbei, wenn Ihr in der Nähe seid.",
    ["Talk to Yesei"] = "Sprecht mit Yesei",
    ["Yes, I cornered your Dakoi, and he gave me this fish for you."] = "Ja, ich drängte den Dakoi in die Ecke, und er gab mir diesen Fisch für Euch.",
    ["Ah, just like my kin. Take this, along with Mudman's blessing. And you're welcome to return for more.\n\nThe Mudman must thrive through the entire New Life season. And, like all of life, it needs care."] = "Als wärt Ihr <<player{einer/eine}>> von uns. Nehmt dies und den Segen des Schlammkerls entgegen. Kommt gern wieder, um noch mehr beizutragen.\n\nDer Schlammkerl muss das ganze Neujahrsfest über kräftig bleiben. Wie alles Leben, braucht er dafür Zuwendung.",
    ["Talk to Dailonda"] = "Sprecht mit Dailonda",
    ["You mentioned a reward?"] = "Ihr erwähntet eine Belohnung?",
    ["Oh, you remember that, do you. Well, what the tusk, it's New Life! You earned the boon and more, and you finally gave me some true competition.\n\nCome back for another swing! Surely there's more Oblivion boulders where that one came from!"] = "Oh, daran erinnert Ihr Euch also noch. Ach, was zum Hauer, es ist schließlich Neujahr! Ihr habt Euch den Segen und mehr verdient, und mir endlich eine richtige Herausforderung verschafft.\n\nKommt gern wieder! Da warten sicher noch mehr Felsen aus dem Reich des Vergessens auf uns!",
    ["Talk to Mahagog"] = "Sprecht mit Mahagog",
    ["You mentioned you were going to throw in something extra, I believe."] = "Ich glaube, Ihr hattet erwähnt, Ihr wolltet noch etwas obendrauf geben.",
    ["As long as a piece of the All-Maker resides in Garth, his mood will always hang like a sharp blade over New Life. \n\nI'll continue to do my best to keep him entertained, but should you return I may call upon you again for assistance. Happy New Life!"] = "Solange Garth ein Teil des Allschöpfers innewohnt, wird seine Laune immer wie eine scharfe Klinge über dem Neujahrsfest hängen.\n\nIch werde weiterhin mein Bestes geben, um ihn bei Stimmung zu halten, aber solltet Ihr zurückkehren, werde ich Eure Hilfe möglicherweise erneut brauchen. Frohes Neujahrsfest!",
    ["Talk to Baldan"] = "Sprecht mit Baldan",
    ["You think?"] = "Meint Ihr?",
    ["Indeed. However, centuries of resentment rests beneath these sands. Return if you can to help Yokuda's waters flow here. Another also approaches who may need your help, too.\n\nBefore I take my leave, here. From the Kogo-Hi."] = "Fürwahr. Allerdings ruhen unter diesen Sanden Jahrhunderte des Grolls. Kommt wieder, wenn Ihr helfen könnt, Yokudas Wasser hier fließen zu lassen. Und da nähert sich noch jemand, der Eure Hilfe brauchen könnte.\n\nBevor ich mich verabschiede, nehmt dies. Von den Kogo-Hi.",
    ["Talk to Hassavir"] = "Sprecht mit Hassavir",
    ["The ritual is complete then?"] = "Dann ist das Ritual vollendet?",
    ["No … but it's like the winds guiding me carried thoughtful eyes, watching my every step. Perhaps it was the heat.\n\nBut I find every ritual helps me understand my own path. And I hope you'll join me again."] = "Nein ... Aber es ist, als trügen die Winde, die mich führten, aufmerksame Augen, die über jeden meiner Schritte wachten. Vielleicht war es auch nur die Hitze.\n\nAber mit jedem Ritual scheint es mir, dass ich meinen eigenen Weg besser verstehe. Und ich hoffe, Ihr werdet mich noch einmal begleiten.",
    ["Talk to Jahesi"] = "Sprecht mit Jahesi",
    ["Did you see someone on your journey?"] = "Habt Ihr auf Eurer Reise jemanden gesehen?",
    ["I regret that it has come to this. A fast moving vampiric change means that Terinvel is a danger to everyone. I must deal with it, as a friend should. \n\nI'm grateful for your steady support and calm demeanor through this. Here's payment as promised."] = "Ich bedauere, dass es hierzu kommen musste. Eine so rapide vampirische Veränderung bedeutet, dass Terinvel eine Gefahr für seine Umgebung darstellt. Ich muss mich darum kümmern, wie eine Freundin das tun sollte.\n\nIch danke Euch für Eure unermüdliche Unterstützung und Euren kühlen Kopf bei dieser Sache. Hier Eure versprochene Belohnung.",
    ["Why does the dark adept put up with that prince?"] = "Warum hält es die Dunkle Adeptin mit diesem Prinzen aus?",
    ["I do not know which warmth I cherish most. That of the sun's light, the burning coals of our nests, or that of my partner who no longer sleeps beside me. May they rest in stone and memory."] = "Ich weiß nicht, welche Wärme ich am liebsten mag. Die des Sonnenlichts, die der brennenden Kohle unserer Nester oder die meines Partners, der nicht länger neben mir schläft. Möge er in Stein und Erinnerung ruhen.",
    ["First, I'll kill you. Then I'll see the end of Captain One-Eye."] = "Zuerst bringe ich Euch um. Dann kümmere ich mich um Kapitän Ein-Auge.",
    ["The Spriggan's going to be ferrying some well-paying passengers off Solstice. I recognize them from back home, but they haven't recognized me yet.\n\nStrange seeing Gahz and Oorbesh be so civil. And I'll be keeping an eye on their … friend."] = "Die Zweigling wird ein paar zahlungskräftige Passagiere von Sonnenwende wegbringen. Ich kenne sie noch von zu Hause, aber sie haben mich noch nicht erkannt.\n\nEs ist seltsam, Gahz und Oorbesh so zivilisiert zu sehen. Und ich werde ihren ... Freund im Auge behalten.",
    ["When activated, plays the lively music box composition \"Grave-Stake Gambol.\""] = "Einmal aktiviert, spielt die Spieluhr ein lebhaftes Arrangement der Komposition „Grabpflock-Tollerei“.",
    ["Music Box, Grave-Stake Gambol"] = "Spieluhr „Grabpflock-Tollerei“^f",
    ["Achievement Furnishings: Solstice"] = "Errungenschaftseinrichtung: östliches Sonnenwende^f",
    ["This small, well-stitched satchel contains a handful of Trade Bars."] = "Diese kleine und sorgfältig genähte Tasche enthält einige Handelsbarrens.",
    ["Trade Bar Satchel"] = "Tasche mit Handelsbarren^f",
    ["Grants an Outfit Style Collectible. Once used, the Outfit Style is available to all characters on your account. Outfit Styles can be used at an Outfit Station to customize your appearance."] = "提供一件装扮样式收藏品。使用后，你账号上的所有角色均可使用该装扮样式。装扮样式可用于在装扮台自定义你的外观。",
    ["Bound Style Page: Nokvroz's Greatsword Replica"] = "约缚样式书页：诺克弗洛兹巨剑复制品",
    ["Ashbound Hall"] = "aschgebundene Halle^fc,in",
    ["Boss Room"] = "Anführerraum^m,in",
    ["Amulet Area"] = "Amulett-Bereich^m,in",
    ["Dealing damage with a Bash or fully-charged Heavy Attack places the <<1>> on your target for <<2>>. While active, you gain <<3>>, increasing damage done by <<4>>, and deal <<5>> more damage to the target and <<6>> less damage to all other enemies. If the enemy dies while marked, you gain <<7>> Stamina or Magicka, based off your highest maximum resource. This effect can trigger up to every <<8>>."] = "Verursacht Ihr Schaden mit einem Wuchtschlag oder einem voll aufgeladenen schweren Angriff, wird Euer Feind <<2>> lang mit <<1>> belegt. Während es aktiv ist, erhaltet Ihr <<3>>, was Euren verursachten Schaden um <<4>> erhöht, und verursacht <<5>> mehr Schaden am Ziel sowie <<6>> weniger Schaden an anderen Zielen. Wenn das Ziel mit aktivem Mal stirbt, gewährt Euch dies <<7>> Ausdauer oder Magicka, abhängig von Eurer höchsten Ressource. Dieser Effekt kann einmal alle <<8>> eintreten.",
    ["Quake"] = "Beben^m",
    ["Stop"] = "Anhalten^N",
    ["Remove"] = "Entfernen^N",
    ["Visability"] = "Sichtbarkeit^f",
    ["Mor Naril Priory"] = "Priorei von Mor Naril^f,in",
    ["Note to Gabrielle"] = "Nachricht an Gabrielle^f",
    ["Search"] = "Durchsuchen",
    ["Destroy"] = "Zerstören",
    ["Mural Dedication"] = "Widmung in einem Wandbild^f",
    ["Writhing Fortress"] = "翻腾堡垒",
    ["Currency Vault"] = "Währungsgewölbe",
    ["The currency vault dynamically shows the amount of gold you currently have. As you earn more gold, more shows up inside the vault. As you spend gold, less gold appears inside the vault."] = "Das Währungsgewölbe zeigt dynamisch die Menge Gold an, die Ihr aktuell besitzt. Je mehr Gold Ihr ansammelt, desto mehr erscheint im Gewölbe. Gebt Ihr Gold aus, erscheint weniger Gold im Gewölbe.",
    ["Bank Safe"] = "Banktresor",
    ["Gain access to the bank safe by acquiring 3,000 favor with your pledged faction. Once acquired, you can access your bank and guild bank via this safe."] = "Ihr erhaltet Zugriff auf den Banktresor, sobald Ihr 3.000 Gunst bei Eurer Fraktion verdient habt. Anschließend könnt Ihr über diesen Tresor auf Eure Bank und die Gildenbank zugreifen.",
    ["Faction Banners"] = "Fraktionsbanner",
    ["Display your allegiance to your faction. After gaining 2,000 favor with your faction, unlock the ability to display their banners in your courtyard."] = "Zeigt Eure Zugehörigkeit zu einer Fraktion. Habt Ihr 2.000 Gunst bei Eurer Fraktion erlangt, könnt Ihr deren Banner auf Eurem Vorplatz aufstellen.",
    ["EMOTE: |c22ADDCSitChair"] = "AKTION: |c22ADDCAuf Stuhl sitzen",
    ["Eastern Solstice Cave Delver"] = "<<player{Höhlenforscher/Höhlenforscherin}>> vom östlichen Sonnenwende",
    ["The Worm Cult trapped four Undaunted heroes within soul-forged weapons across Solstice. Free the trapped heroes and learn the truth of their tale in a melancholy tome."] = "Der Wurmkult hat vier Unerschrockenen-Helden in seelengeschmiedeten Waffen auf ganz Sonnenwende gefangen. Befreit die gefangenen Helden und erfahrt die Wahrheit über ihre Geschichte in einem melancholischen Folianten.",
    ["Your scales should mend in no time, egg-kin. Catch your breath, then make your way back to your village."] = "Eure Schuppen sollten schnell wieder heilen, Eibruder. Kommt zu Atem und geht dann zurück ins Dorf.",
    ["You have life again. Use it and move forward. Without sadness. Without regret."] = "Ihr habt wieder ein Leben. Nutzt es und schreitet voran. Ohne Trauer. Ohne Bedauern.",
    ["I smell blood in the water. It's time to fight!"] = "Ich rieche Blut im Wasser. Zeit zu kämpfen!",
    ["No! Just when Sharadak had her in his clutches, she slips away. Torment! Madness! This one may never recover! … Which way did she go?"] = "Nein! Gerade, als Sharadak sie in seinen Fängen hatte, entwischt sie ihm. Qual! Wahnsinn! Dieser wird sich niemals erholen! ... In welche Richtung ist sie entkommen?",
    ["Well, maybe I'll … I'll just scrap this song."] = "Hmm ... Vielleicht verwerfe ich dieses Lied doch.",
    ["Vanus's dupe and Meridia's fool. Have you come to witness my triumph?"] = "Vanus' Tölpel und Meridias Narr. Kommt näher und erlebt meinen Triumph!",
    ["Come on, Jeetra—give me a little credit. I'm just looking. Something's off about this door, I'm trying to figure out what."] = "Kommt schon, Jeetra. Schenkt mir ein wenig Vertrauen. Ich schaue nur. Etwas stimmt mit dieser Tür nicht und ich versuche herauszufinden, was.",
    ["Destroy the soul flayer, mainlander! It blocks our path!"] = "Zerstört den Seelenschinder, <<player{Festländer/Festländerin}>>! Er versperrt uns den Weg!",
    ["When you have the Embellished Dance Card, Rosy Boutonniere, and Sanguine's Goodbye Kiss: \nUse to combine into the Roseblood Wings Recall customized action."] = "Besitzt Ihr die verzierte Tanzkarte, die rosige Knopflochblume und Sanguines Abschiedskuss, könnt Ihr sie benutzen und zur angepassten Aktion „Rückruf der Rosenblut-Schwingen“ kombinieren.",
    ["Today's New Life offering is complete. I should speak to Lanullin and ask about my reward."] = "Die Neujahrsgabe für heute ist abgeschlossen. Ich sollte mit Lanullin sprechen und nach meiner Belohnung fragen.",
    ["I delivered the New Life offering to Lanullin's elder. I should let her know I completed my task."] = "Ich überbrachte für Lanullin die Neujahrsgabe. Ich sollte sie wissen lassen, dass ich meinen Auftrag abgeschlossen habe.",
    ["I need to prepare a banana surprise offering for Lanullin's elder. The grocers and taverns nearby should have a recipe and cooking fire if I need them."] = "Ich muss eine Bananenüberraschung für Lanullins Ältesten zubereiten. Die Krämer und Tavernen in der Nähe sollten ein Rezept und eine Feuerstelle haben, falls ich so etwas brauche.",
    ["I need to prepare a carrot soup offering for Lanullin's elder. The grocers and taverns nearby should have a recipe and cooking fire if I need them."] = "Ich muss eine Karottensuppe für Lanullins Älteste zubereiten. Die Krämer und Tavernen in der Nähe sollten ein Rezept und eine Feuerstelle haben, falls ich so etwas brauche.",
    ["I need to prepare a baked potato offering for Lanullin's elder. The grocers and taverns nearby should have a recipe and cooking fire if I need them."] = "Ich muss eine Ofenkartoffel für Lanullins Ältesten zubereiten. Die Krämer und Tavernen in der Nähe sollten ein Rezept und eine Feuerstelle haben, falls ich so etwas brauche.",
    ["Time to deliver the offering. The list Lanullin gave me should say whom to offer this to and where."] = "Zeit, die Gabe zu überbringen. Die Liste, die mir Lanullin gab, sollte mir verraten, wem und wohin ich diese Gabe bringen soll.",
    ["Tibarr wants me to steal a coin from the lair of Rawl'kha's Dragon. He mentioned the lair was in a cavern nearby."] = "Tibarr will, dass ich eine Münze aus dem Hort des Drachen von Knurr'kha stehle. Er hatte erwähnt, dass der Bau in einer Höhle in der Nähe ist.",
    ["I completed Tibarr's New Life festivity and gave the Dragon's coin to the Orc beggar. Now to claim my own reward from Tibarr."] = "Ich schloss Tibarrs Neujahrsfeierlichkeit ab und gab die Münze des Drachen dem Orkbettler. Nun muss ich mir meine Belohnung bei Tibarr holen.",
    ["I swiped the Dragon's coin and donated it to the Orc beggar. Now I should report back to Tibarr."] = "Ich stibitzte die Münze des Drachen und spendete sie dem Orkbettler. Jetzt sollte ich mich bei Tibarr melden.",
    ["I swiped the Dragon's coin. Tibarr wants me to give it to the Orc beggar, Yarg. I should talk to him and give him the coin."] = "Ich stibitzte die Münze des Drachen. Tibarr will, dass ich sie dem Orkbettler Yarg gebe. Ich sollte mit ihm sprechen und ihm die Münze geben.",
    ["Yesei last saw the Dakoi in the streams near Stormhold's outskirts. I should start fishing there."] = "Yesei sagte, der Dakoi wurde zuletzt in den Bächen am Rand von Sturmfeste gesehen. Dort sollte ich mit dem Angeln anfangen.",
    ["I returned to Yesei with fish from the Dakoi. I should speak to him and ask about my reward."] = "Ich kehrte mit dem Fisch zu Yesei zurück. Ich sollte mit ihm sprechen und nach meiner Belohnung fragen.",
    ["I caught the Dakoi, revealed to be an Argonian acting like a fish. He gave me one to hand to Yesei. I should return to him."] = "Ich fing den Dakoi: Er stellte sich als Argonier heraus, der sich nur verhielt wie ein Fisch. Er gab mir einen Fisch, den ich Yesei geben soll, wenn ich zu ihm zurückkehre.",
    ["Dailonda said she needs fresh mud to spring the Mudman to life. Time to dig."] = "Dailonda sagte, sie brauche frischen Schlamm, um den Schlammkerl lebendig zu machen. Zeit zum Graben.",
    ["I smeared the mud and helped Dailonda complete the Mudman effigy. I should speak to her and ask about my reward."] = "Ich schmierte den Schlamm auf den Schlammkerl und half Dailonda bei der Fertigstellung des Abbilds. Ich sollte mit ihr über meine Belohnung sprechen.",
    ["Mahagog said I could find an Orsimer hammer to use for the challenge at a blacksmith's station in the fortress. I should get it and try to smash the Oblivion boulder."] = "Mahagog sagte, ich finde einen Orsimer-Hammer für die Herausforderung bei einer Schmiede in der Festung. Ich sollte ihn holen und danach versuchen, den Felsen aus dem Reich des Vergessens zu zerschmettern.",
    ["I proved my strength and destroyed the Oblivion boulder. Time to speak to Mahagog about my reward."] = "Ich stellte meine Stärke unter Beweis und zerstörte den Felsen aus dem Reich des Vergessens. Es wird Zeit, mit Mahagog über meine Belohnung zu sprechen.",
    ["I need to find some honeycomb to put Garth in a good mood for New Life. The hermit said the forests near Hunter's Glade should have some."] = "Ich muss eine Honigwabe finden, um Garth zum Neujahrsfest gute Laune zu machen. Der Einsiedler meinte, es gäbe welche in den Wäldern bei der Lichtung des Jägers.",
    ["I fed Garth the honeycomb and saved all of Tamriel, according to the hermit. I should speak to him and ask about my reward."] = "Ich fütterte Garth mit der Honigwabe und rettete so dem Einsiedler zufolge ganz Tamriel. Ich sollte mit ihm sprechen und nach meiner Belohnung fragen.",
    ["I need to fill the waterskin with Yokuda's waters in the west. Once done, I can perform the ritual of Anseilak at Motalion Necropolis."] = "Ich muss den Trinkschlauch im Westen mit Yokudas Wassern füllen. Sobald dies getan ist, kann ich das Ritual namens Anseilak in der Nekropole Motalion durchführen.",
    ["I helped Hassavir complete his pilgrimage and performed Anseilak for the fallen Yokudan mages. I should speak to him and ask about my reward."] = "Ich half Hassavir, seine Pilgerreise abzuschließen und führte das Ritual namens Anseilak für die gefallenen yokudanischen Magier durch. Ich sollte mit ihm sprechen und nach meiner Belohnung fragen.",
    ["Lanullin is preparing her offerings to the elders in Auridon. I should speak to her and learn what I can do to help."] = "Lanullin bereitet ihre Gaben für die Ältesten in Auridon zu. Ich sollte mit ihr sprechen und nachhorchen, was ich tun kann, um zu helfen.",
    ["I should travel to Rawl'kha and find Tibarr to learn more about his New Life festivity."] = "Ich sollte nach Knurr'kha reisen und Tibarr suchen, um mehr über seine Neujahrsfeierlichkeit zu erfahren.",
    ["I should look for Yesei in Stormhold and see if he needs help catching the Dakoi fish."] = "Ich sollte Yesei in Sturmfeste aufsuchen und herausfinden, ob er Hilfe beim Fangen des Dakoi-Fischs braucht.",
    ["I should speak to Dailonda in Elden Root to find out more about what she needs help with."] = "Ich sollte mit Dailonda in Eldenwurz sprechen, um mehr darüber zu erfahren, wobei sie Hilfe braucht.",
    ["Mahagog is hosting the festivity with a group of Orcs at Stonetooth Fortress. I should speak to him to learn more about this contest of strength."] = "Mahagog richtet das Fest mit einer Gruppe von Orks an der Steinzahn-Festung aus. Ich sollte mit ihm sprechen, um mehr über diesen Stärke-Wettbewerb zu erfahren.",
    ["The traveler was said to be seen out in Sentinel asking for help. I should start there and speak to them."] = "Die Person auf Reisen wurde angeblich gesehen, wie sie draußen in Schildwacht um Hilfe bat. Ich sollte dort anfangen und mit ihr sprechen.",
    ["Anicus mentioned the hermit was spotted in the Rift. I should speak to him and learn more about his pet bear's needs."] = "Anicus erwähnte, dass der Einsiedler in Rift gesehen wurde. Ich sollte mit ihm sprechen und mehr über die Bedürfnisse seines zahmen Bären erfahren.",
    ["I helped Jahesi perform Anseilak and gave peace to the fallen Yokudan mages. I should speak to her about my reward."] = "Ich half Jahesi, das Ritual namens Anseilak durchzuführen und den gefallenen yokudanischen Magiern Frieden zu schenken. Ich sollte mit ihr sprechen und nach meiner Belohnung fragen.",
    ["I need bait to catch the Dakoi fish. Yesei mentioned the Shadowscale camp west from Stormhold might have a bottle of bloodwine that could work."] = "Ich brauche einen Köder, um den Dakoi-Fisch zu fangen: Yesei erwähnte das Schattenschuppenlager westlich von Sturmfeste. Dort könnte ich eine Flasche Blutwein finden, die sich als Köder eignet.",
    ["Mahagog mentioned he fought a group of Daedra west of Stonetooth Fortress that left behind an Oblivion boulder for us to smash. I should search the area, find the boulder, and mark its location on my map."] = "Mahagog erwähnte, er hätte westlich der Steinzahn-Festung gegen eine Gruppe von Daedra gekämpft. Dabei blieb wohl auch ein Felsen aus dem Reich des Vergessens zurück, den wir zerschmettern können. Ich sollte das Gebiet durchsuchen, den Felsen finden und seinen Standort auf meiner Karte markieren.",
    ["I found the strange Oblivion boulder. I should return to Mahagog and let him know exactly where it is."] = "Ich fand den seltsamen Felsen aus dem Reich des Vergessens. Ich sollte zu Mahagog zurückkehren und ihn wissen lassen, wo genau er liegt.",
    ["Mahagog is waiting for me. I should tell him about the boulder I found for our challenge."] = "Mahagog wartet auf mich. Ich sollte ihm von dem Felsen erzählen, den ich für unsere Herausforderung fand.",
    ["Sirilonwe noticed an abandoned camp to the southeast. She guesses that it might belong to Terinvel and Ormard. I should search it for evidence of where they went."] = "Sirilonwe hat im Südosten ein verlassenes Lager bemerkt. Sie vermutet, dass es zu Terinvel und Ormard gehört. Ich sollte es nach Hinweisen darauf durchsuchen, wo die beiden hin sind.",
    ["I offered Sirilonwe advice about how to handle Terinvel's transformation into a vampire. It remains to be seen if she takes it. I should talk to her about my reward."] = "Ich bot Sirilonwe meinen Rat an, wie sie mit Terinvels Transformation in einen Vampir umgehen kann. Ob sie dem Gehör schenkt, wird sich zeigen. Ich sollte mit ihr über meine Belohnung sprechen.",
    ["The abandoned campsite outside Ashbound Hall definitely belonged to Terinvel and Ormard. I found notes from them claiming to know of a side entrance into the Hall. I should talk to Sirilonwe about this."] = "Das verlassene Lager vor der Aschgebundenen Halle gehörte definitiv zu Terinvel und Ormard. Ich fand Notizen, laut deren sie von einem Nebeneingang in die Halle wissen. Ich sollte mit Sirilonwe darüber sprechen.",
    ["Terinvel's dropped note describes a cave entrance that leads inside Ashbound Hall. I should explore to the southwest to find it."] = "Terinvels Notiz beschreibt einen Höhleneingang, der in die Aschgebundenen Halle führt. Ich sollte im Südwesten nachsehen, um ihn zu finden.",
    ["I found a crack in the stone that could lead into some caves. This might be the side entrance into Ashbound Hall that Terinvel mentioned in his notes. I should head in and see where it leads me."] = "Ich fand einen Riss im Stein, der in eine Höhle führen könnte. Vielleicht ist dies der Eingang zur Aschgebundenen Halle, den Terinvel in seinen Notizen erwähnte. Ich sollte hineingehen und sehen, wohin er mich führt.",
    ["A Stirk Fellowship scout named Mihnassi told me about the missing Terinvel and Sirilonwe's need for aid. She said I could find the academic on the road north of Ashbound Hall. I should track her down."] = "Eine Späherin der Stirk-Gefolgschaft namens Mihnassi erzählte mir vom vermissten Terinvel und davon, dass Sirilonwe Hilfe benötigt. Sie sagte, ich könne die Gelehrte auf der Straße zur Aschgebundenen Halle finden. Ich sollte sie ausfindig machen.",
    ["The crack in the wall led into a cave. I see an opening to a building that may be Ashbound Hall. I should talk to Sirilonwe to discuss our next move."] = "Der Riss in der Wand führte zu einer Höhle. Ich kann eine Öffnung zu einem Gebäude erkennen, das die Aschgebundene Halle sein könnte. Ich sollte mit Sirilonwe besprechen, wie wir weitermachen.",
    ["Sirilonwe confirmed that the cave opens into Ashbound Hall. She urged caution as we explore the prison. Vampires lurk everywhere. I should start my search for Terinvel."] = "Sirilonwe bestätigte, dass die Höhle in die Aschgebundene Halle führt. Sie mahnte zur Vorsicht, während wir das Gefängnis erkunden. Es lauern überall Vampire. Ich sollte mit der Suche nach Terinvel beginnen.",
    ["My search revealed a medallion etched with strange characters. I also found a note describing a method to unlock the sealed door. I need to show these to Sirilonwe."] = "Meine Suche brachte ein Medaillon zutage, das mit seltsamen Zeichen versehen ist. Ich fand auch eine Notiz, die beschreibt, wie die versiegelte Tür geöffnet werden kann. Ich muss beides Sirilonwe zeigen.",
    ["Sirilonwe identified the medallion I found as the Aspect of Brutality. It's part of a system that unlocks doors around Ashbound Hall. The note I found describes the Aspect's correct arrangement. I should place this on the unlocking"] = "Sirilonwe identifizierte das Medaillon, das ich fand, als Aspekt der Brutalität. Er gehört zu einem System, das in der Aschgebundenen Halle Türen öffnet. In der Notiz, die ich gefunden habe, ist die korrekte Anordnung des Aspekts beschrieben. Ich sollte ihn platzieren.",
    ["A young vampire revealed herself to us and claimed she meant no harm. It seems she's the source of the mysterious whispering we heard. I should find out why she's following us."] = "Eine junge Vampirin gab sich uns zu erkennen und sagte, sie wolle uns nichts antun. Scheinbar ging von ihr das rätselhafte Flüstern aus, das wir vernahmen. Ich sollte herausfinden, weshalb sie uns folgt.",
    ["Azartha gave us some helpful information for dealing with Ashbound Hall. Rooms that are more brightly lit than others will keep us safe. Apparently we can find a map in one of those rooms. I should resume my search of the prison."] = "Azatha versorgte uns mit hilfreichen Informationen im Umgang mit der Aschgebundenen Halle. In Räumen, die heller erleuchtet sind als andere, sind wir sicher. Offenbar finden wir in einem dieser Räume eine Karte. Ich sollte mit der Durchsuchung des Gefängnisses fortfahren.",
    ["We found another room bathed in purple light. Azatha mentioned we might find a map for Ashbound Hall in a room like this. I should search for one."] = "Wir haben noch einen Raum gefunden, der in violettes Licht getaucht ist. Azatha meinte, in solch einem Raum könnten wir eine Karte der Aschgebundenen Halle finden. Nach der sollte ich Ausschau halten.",
    ["Our exploration of Ashbound Hall brought us to a magically sealed door. We found a safe room nearby that could provide clues to opening the door. I should look around for anything that stands out."] = "Unsere Erkundung der Aschgebundenen Halle führte uns zu einer magisch versiegelten Tür. In der Nähe fanden wir einen sicheren Raum, der uns Hinweise geben könnte, wie man die Tür öffnet. Ich sollte mich nach Dingen umsehen, die mir auffällig erscheinen.",
    ["During my search for a map of Ashbound Hall, I also found another Aspect medallion. Maybe Sirilonwe can tell me which one it is. I should show it to her along with the map."] = "Auf meiner Suche nach einer Karte der Aschgebundenen Halle fand ich auch noch ein weiteres Aspektmedaillon. Vielleicht kann Sirilonwe mir sagen, um welches es sich handelt. Ich sollte ihr die Karte und den Aspekt zeigen.",
    ["As Sirilonwe and I crossed a bridge, we heard whispering from the shadows. The whispers seem to be talking about us. I should hunt down the source to see if its dangerous."] = "Als Sirilonwe und ich eine Brücke überquerten, hörten wir ein Flüstern aus den Schatten. Das Flüstern scheint mit uns zu sprechen. Ich sollte seine Quelle ausfindig machen, um zu sehen, ob es gefährlich ist.",
    ["With the help of Sirilonwe's spell, I was able to clear the rubble from the bridge. Now I can continue my search of Ashbound Hall for Terinvel."] = "Mithilfe von Sirilonwes Zauber konnte ich die Brücke von den Trümmern befreien. Nun kann ich meine Suche nach Terinvel in der Aschgebundenen Halle fortsetzen.",
    ["We entered a new section of Ashbound Hall and found another vampire calling out for help. Like Azatha, he claims to be harmless and didn't attack on sight. I should talk to him to see if he can provide information for finding Terinvel."] = "Wir betraten einen neuen Bereich der Aschgebundenen Halle und stießen auf einen weiteren Vampir, der um Hilfe bittet. Wie Azatha sagt auch er, er sei harmlos, und hat uns nicht beim ersten Anblick angegriffen. Ich sollte mit ihm sprechen und herausfinden, ob er Informationen hat, die uns bei der Suche nach Terinvel helfen können.",
    ["Despite Sirilonwe healing Liviano, he decided to attack us. She turned him into ashes. I should search his remains to see if he did have the Aspect he claimed to."] = "Obwohl Sirilonwe Livanio geheilt hat, griff er an. Sie verwandelte ihn in Asche. Ich sollte in seinen Überresten nachsehen, ob er den Aspekt bei sich trug, wie er es vorgab.",
    ["Fortunately, I found an Aspect among Livanio's ashes. Lucky for us, Sirilonwe's fire spell didn't melt it. I should check on her to make sure she's all right after this attack."] = "Zum Glück fand ich in Livanios Asche einen Aspekt. Erfreulicherweise hat Sirilonwes Feuer ihn nicht geschmolzen. Ich sollte nach ihr sehen und nachfragen, ob nach diesem Angriff bei ihr alles in Ordnung ist.",
    ["We unlocked the door by using the Aspects, and entered the next section of Ashbound Hall. Now we can continue our search of this prison for Terinvel."] = "Mit den Aspekten konnten wir die Tür öffnen und den nächsten Abschnitt der Aschgebundenen Halle betreten. Nun suchen wir in diesem Gefängnis weiter nach Terinvel.",
    ["Sirilonwe feels justified in killing Livanio in self-defense. Plus, now we have another important Aspect to help us through this prison. I should follow her into the next section."] = "Sirilonwe betrachtet es als gerechtfertigt, dass sie Livanio aus Notwehr getötet hat. Zudem verfügen wir nun über einen weiteren wichtigen Aspekt, der uns auf dem Weg durch dieses Gefängnis von Nutzen ist. Ich sollte ihr in den nächsten Abschnitt folgen.",
    ["The injured Ormard implied that he hid an Aspect somewhere in the central courtyard. I need to look through all this damage until I find it."] = "Der verletzte Ormard deutete an, dass er im Haupthof einen Aspekt versteckt hat. Ich muss gründlich in diesem Chaos suchen, um ihn zu finden.",
    ["I managed to find an Aspect among the rubble of the central courtyard. Ormard didn't do that good of a job hiding it. I should show it to Sirilonwe."] = "Ich konnte im Schutt des Haupthofs einen Aspekt finden. Ormard hat ihn nicht sonderlich gut versteckt. Ich sollte ihn Sirilonwe zeigen.",
    ["The only way out of the central courtyard is through another magically sealed door. I need to place the Aspects in the proper order to unlock the magic."] = "Der einzige Weg aus diesem Haupthof heraus führt durch eine weitere magisch versiegelte Tür. Ich muss die Aspekte in der richtigen Anordnung platzieren, um die Magie freizugeben.",
    ["We finally caught up with Terinvel. Unfortunately, a powerful vampire named the Elder has captured and bound him. I only see one way to get him free. I should kill the Elder."] = "Endlich haben wir Terinvel eingeholt. Leider hat ihn eine mächtige Vampirin, die sich die Älteste nennt, gefangen genommen und festgebunden. Ich sehe nur einen Weg, ihn zu befreien. Ich sollte die Älteste töten.",
    ["Terinvel is free, even if he doesn't immediately appreciate it. Sirilonwe conjured a portal so that we can leave Ashbound Hall. I should join her outside."] = "Terinvel ist frei, auch wenn er das nicht direkt zu schätzen weiß. Sirilonwe hat ein Portal beschworen, damit wir die Aschgebundene Halle verlassen können. Ich sollte mit ihr nach draußen gehen.",
    ["I stepped through the portal and arrived outside Ashbound Hall. I can hear Terinvel and Sirilonwe argue with each other. I should check on the newly rescued researcher and see how he feels."] = "Ich trat durch das Portal und landete vor der Aschgebundenen Halle. Ich höre Terinvel und Sirilonwe miteinander streiten. Ich sollte mich erkundigen, wie es dem frisch geretteten Forscher geht.",
    ["Despite all our efforts, Terinvel didn't escape unscathed. He admits that the Elder passed on vampirism to him. He seems quite excited about the power growing inside him. I should talk to Sirilonwe about this."] = "Trotz unsere Bemühungen entkam Terinvel nicht unversehrt. Er gibt zu, dass die Älteste den Vampirismus an ihn weitergegeben hat. Er scheint begeistert von der Macht, die in seinem Inneren wächst. Ich sollte darüber mit Sirilonwe sprechen.",
    ["After Sirilonwe cast her spell, ghostly versions of Terinvel and Ormard appeared. This was a recreation of a moment in the past. They discussed their plans to go deeper into the Ashbound Halls. I should talk to Sirilonwe about this."] = "Nachdem Sirilonwe ihren Zauber gewirkt hat, erschienen Terinvel und Ormard als geisterhafte Versionen. Es handelte sich um die Nachstellung eines Moments in der Vergangenheit. Sie diskutierten darüber, tiefer in die Aschgebundene Halle vorzudringen. Ich sollte mit Sirilonwe darüber sprechen.",
    ["With our combined strength, Sirilonwe and I managed to defeat the Elder. Terinvel is now free, if a bit ungrateful. I should wait until he's on his feet to see what we do next."] = "Mit vereinten Kräften konnten Sirilonwe und ich die Älteste besiegen. Terinvel ist jetzt frei, allerdings etwas undankbar. Ich sollte warten, bis er wieder auf den Beinen ist, um zu sehen, was wir als Nächstes tun.",
    ["When I placed the Aspect of Brutality into the mechanism, the ward disappeared from the door. Sirilonwe and I should continue our search of Ashbound Hall for Terinvel."] = "Als ich den Aspekt der Brutalität im Mechanismus platzierte, verschwand der Schutzzauber von der Tür. Sirilonwe und ich sollten unsere Suche nach Terinvel in der Aschgebundenen Halle fortsetzen.",
    ["Now that we have a rough map of Ashbound Hall, finding Terinvel should be slightly easier. Time to continue forward with our search."] = "Mit der groben Karte der Aschgebundenen Halle sollte es einfacher werden, Terinvel zu finden. Es wird Zeit, unsere Suche fortzusetzen.",
    ["Sirilonwe has a spell that can clear the rubble that blocks our path. Once she starts casting, I need to smash the rubble."] = "Sirilonwe verfügt über eine Zauber, der den Schutt aus unserem Weg räumen kann. Sobald sie anfängt, ihn zu wirken, muss ich den Schutt zerhauen.",
    ["Sirilonwe and I finally reached the central courtyard and it's in shambles. However, we did manage to find an injured Ormard laying on the ground. He claims to have expected us. I should press him to tell me where Terinvel went."] = "Sirilonwe und ich haben endlich den Haupthof erreicht. Er liegt in Trümmern. Wir fanden einen verletzten Ormard auf dem Boden vor. Er meint, er habe uns erwartet. Ich sollte ihn zwingen, mir zu sagen, wohin Terinvel gegangen ist.",
    ["Sirilowe spotted a camp fire tucked away in a heavily damaged area of the Hall. She thinks it's worth searching. I should look through the camp for any clues."] = "Sirilonwe entdeckte in einem stark zerstörten Bereich der halle ein Lagerfeuer. Sie glaubt, es lohne sich, mal nachzuschauen. Ich sollte sehen, ob ich im Lager Hinweise finde.",
    ["Ashbound Hall's crash landing into Solstice created rubble everywhere. Some of it blocks a bridge we need to cross. I should talk to Sirilonwe about how to clear it."] = "Durch die harte Landung der Aschgebundenen Halle auf Sonnenwende liegen überall Trümmer herum. Diese versperren uns den Weg über eine Brücke. Ich sollte mit Sirilonwe sprechen um zu überlegen, wie wir sie räumen.",
    ["I found a hat that Sirilonwe claims belong to Ormard. Apparently it spurred an idea in her. I should watch what comes from her spell."] = "Ich fand einen Hut, von dem Sirilonwe behauptet, er gehöre Ormard. Das brachte sie offenbar auf eine Idee. Ich sollte beobachten, was ihr Zauber bewirkt.",
    ["In the memory that Sirilonwe recreated, Ormard wanted to get to a crater that's just ahead. Now we have a direction for a search. I should find this crater."] = "In der Erinnerung, die Sirilonwe wiederhergestellt hat, wollte Ormard zu einem Krater direkt vor uns. Jetzt wissen wir, in welche Richtung wir suchen müssen. Ich sollte den Krater finden.",
    ["We reached the area of Ashbound Hall that Ormard referred to as a crater. It certainly matches the title. Should continue my search for Terinvel by crossing it."] = "Wir sind in dem Bereich angekommen, den Ormard einen Krater nannte. Der Name passt zumindest. Ich sollte ihn überqueren, um die Suche nach Terinvel fortzusetzen.",
    ["We crossed through the crater, but saw no sign of Terinvel or Ormard. Sirilonwe suggested we keep heading in this direction. Perhaps we're hot on their heels. I should continue my search of Ashbound Hall."] = "Wir haben den Krater überwunden, aber noch keine Spur von Terinvel oder Ormard. Sirilonwe schlug vor, weiter in die Richtung zu gehen. Vielleicht sind wir ihnen dicht auf den Fersen. Ich sollte die Aschgebundene Halle weiter durchkämmen.",
    ["Sirilonwe and I came across another door sealed with magic. Looks like I need to use the Aspects we collected to unlock it. I should find the right placement for the medallions to unlock the door."] = "Sirilonwe und ich sind an einer weiteren magisch versiegelten Tür angelangt. Sieht aus, als müsste ich die Aspekte, die wir eingesammelt haben, einsetzen, um sie zu öffnen. Ich sollte herausfinden, wie die Medaillons platziert werden müssen.",
    ["I placed all the Aspects in their proper spot and unlocked the door. According to Ormard, Terinvel should be just beyond, but he'll be in the company of someone called the Elder. I should go confront her so we can get out of here."] = "Ich habe alle Aspekte an den vorgesehenen Stellen platziert und die Tür geöffnet. Laut Ormard sollte Terinvel direkt dahinter sein, doch jemand namens die Älteste wird bei ihm sein. Ich sollte ihr entgegentreten, damit wir hier raus können.",
    ["For Lanullin, celebrating New Life involves giving back to the esteemed elders of her community through good meals. I agreed to help her prepare and deliver them."] = "Für Lanullin gehört es zum Neujahrsfest, dass sie den geschätzten Ältesten ihrer Gemeinschaft etwas zurückgibt, und zwar in Form feiner Speisen. Ich willigte ein, ihr dabei zu helfen, diese zuzubereiten und auszuliefern.",
    ["Food for New Life"] = "Neujahrsspeisen",
    ["I met a Khajiit in Rawl'kha who asked me to try and steal coin from a Dragon for his New Life festivity, and then give it to a needy Orc nearby. Apparently, its tricks are challenging to some. I agreed to participate."] = "Ich traf einen Khajiit in Knurr'kha, der mich bat, einem Drachen Münzen für seine Neujahrsfeierlichkeiten zu stehlen. Diese soll ich dann einem bedürftigen Ork in der Nähe geben. Anscheinend sind seine Tricks für manche knifflig. Ich willigte ein, mitzumachen.",
    ["The Dragon's Hoard"] = "Der Drachenhort",
    ["I met an Argonian angler in Stormhold frustrated over not being able to catch the Dakoi, a special fish that's said to appear every New Life festival and bring good fortune. I agreed to hunt and catch the Dakoi for him."] = "Ich traf in Sturmfeste einen argonischen Angler, der sich darüber ärgerte, den Dakoi nicht fangen zu können: einen besonderen Fisch, der zum Neujahrsfest erscheinen und Glück bringen soll. Ich willigte ein, den Dakoi für ihn zu fangen.",
    ["The Hunt for Dakoi"] = "Die Jagd nach dem Dakoi",
    ["I met a Wood Elf in Grahtwood trying to construct a Mudman effigy for the New Life festival to bless all of Tamriel's green. I agreed to help her gather mud and complete the effigy since her kin aren't there to help."] = "Ich traf eine Waldelfin in Grahtwald, die ein Schlammkerl-Abbild erschaffen will, damit das Neujahrsfest Tamriels Grün segnet. Ich willigte ein, ihr beim Sammeln des Schlamms zu helfen und das Abbild zu vollenden, da ihre Familie nicht da ist, um zu helfen.",
    ["The Mudman"] = "Der Schlammkerl",
    ["I met a group of Orcs in Stonetooth Fortress breaking boulders for Betnikh's Boon during the New Life Festival. Their leader proposed I search an area where he fought Daedra for a stronger boulder to break. I accepted his challenge."] = "Ich traf in der Steinzahn-Festung eine Gruppe Orks, die Felsbrocken für Betnikhs Segen während des Neujahrsfests zerschmettert. Ihr Anführer schlug vor, dass ich in einer Gegend, in der er Daedra bekämpfte, nach einem stärkeren Felsen zum Zerschmettern suche. Ich nahm die Herausforderung an.",
    ["Betnihk's Boon"] = "Betnikhs Segen",
    ["A member of the Skaal tribe believes the mood of his bear, Garth, during New Life, will determine the fate of Tamriel. He believes honeycomb might make him happy. I agreed to help him."] = "Ein Mitglied des Skaal-Stamms glaubt, die Laune seines Bären beim Neujahrsfest entscheide über das Schicksal von Tamriel. Er glaubt, eine Honigwabe würde ihn glücklich machen. Ich willigte ein, ihm zu helfen.",
    ["The Judgment of Garth"] = "Garths Urteil",
    ["I met a wandering traveler out in Sentinel on pilgrimage to give fallen Yokudan mages Anseilak, a ritual that brings them peace. However, since he's unable to complete the journey, I agreed to help him."] = "Ich traf draußen in Schildwacht auf jemanden auf Pilgerfahrt, der gefallenen yokudanischen Magiern Anseilak angedeihen lassen will: ein Ritual, das ihnen Frieden schenkt. Da die betreffende Person jedoch nicht in der Lage ist, ihre Reise zu Ende zu bringen, willigte ich ein, ihr zu helfen.",
    ["The Desert and the Sea"] = "Die Wüste und das Meer",
    ["Two academics, Sirilonwe and Terinvel, came to study Ashbound Hall, a vampire prison that arrived with the planemeld on Solstice. However, Terinvel went missing and Sirilonwe needs help finding him among the deadly vampires."] = "Zwei Gelehrte, Sirilonwe und Terinvel, sind gekommen, um die Aschgebundene Halle zu erforschen, ein Vampirgefängnis, das mit der Ebenenverschmelzung nach Sonnenwende kam. Doch Terinvel wird vermisst und Sirilonwe braucht Hilfe dabei, ihn unter den tödlichen Vampiren zu finden.",
    ["Antique Map of Solstice"] = "antike Karte von Sonnenwende^f",
    ["A simple stone for a complex task. To connect a family through the ages. Stone is chipped to have many small indentations. Stone-Nest tradition says each face retains some flavor, some memory, of meals past."] = "Ein simpler Stein für eine komplexe Aufgabe. Er verbindet eine Familie über die Zeitalter hinweg. Der Stein wird behauen, sodass kleine Einkerbungen entstehen. Der Steinnest-Tradition zufolge bewahrt jede Oberflächenstruktur einen eigenen Geschmack, eine Erinnerung an vergangene Mahlzeiten.",
    ["Five is a number that comes up a lot with Hircine. These fangs represent the Spear of Bitter Mercy, also called Spear with Five Points. They would have been fixed in a warmask belonging to a great chief of the Ket Keptu."] = "Die Zahl Fünf ist fest mit Hircine verbunden. Diese Fangzähne stehen für den Speer der Bitteren Gnade, der auch Fünfzackiger Speer genannt wird. Sie waren an einer Kriegsmaske befestigt, die einem großen Häuptling der Ket Keptu gehörte.",
    ["Ah, of course! The Ket Keptu were hunters and warrior-smiths, a people devoted to the Lord of the Hunt. To carry the Spear of Bitter Mercy was a high honor for their great champions. Whoever wore this warmask was indeed favored by Hircine!"] = "Ah, natürlich! Die Ket Keptu waren Jäger und Kriegerschmiede, ein Volk, das dem Fürst der Jagd treu ergeben war. Den Speer der Bitteren Gnade zu tragen, war eine große Ehre für ihre großen Champions. Wer diese Kriegsmaske trug, war wahrlich von Hircine gesegnet!",
    ["I practice conjuration magic."] = "Ich bin <<player{Zauberer/Zauberin}>> und praktiziere Beschwörungsmagie.",
    ["Day 1\n\nNo wonder we're the only fools willing to walk into this deathtrap. This side of Solstice is nothing but destruction. Thankfully, some soldiers from this Stirk Fellowship helped us avoid some Daedra and a Worm Cult patrol.\n\n Sadryn promises a fortune so big I'll never have to open my toolbox again. And he really means it. After we finish this job and I hand over my trap designs, they're his for good.\n\nHonestly, it feels like giving up part of my identity, but mother needs the gold. I hate seeing her like this. She barely even recognizes me anymore. Her ailment is worsening.\n\n* * *\nDay 2\n\nWe finally made camp in some relatively calm part of Eastern Solstice, and yet my mind still battles over whether I can actually fulfill my end of this bargain. No, I'm sure now.\n\nI'll set the traps tomorrow, but I've decided I can't part with my plans for how to build them. Father helped me design these. Building every trap makes it feel like he's still with me, and mother wouldn't want me to sell my knowledge like this, either.\n\nI'll tell Sadryn and still help him complete this hunt. I need the gold. But after that we'll need to settle on a new deal.\n\n* * *\nSadryn became so angry when I told him, he went completely mad! Oh gods, he stabbed me! I managed to slash his chest, drive him off. I should have aimed for his heart.\n\nIt hurts so much. The blood won't stop flowing. I'm hiding, but I hear him looking for me. It's getting harder to write.\n\nMother, I'm sor—"] = "Tag 1\n\nKein Wunder, dass wir die einzigen Narren sind, die bereitwillig in diese Todesfalle marschieren. Auf dieser Seite von Sonnenwende ist alles vernichtet. Zum Glück halfen uns einige Soldaten der Stirk-Gefolgschaft gegen ein paar Daedra und eine Streife des Wurmkults.\n\n Sadryn verspricht ein derart gewaltiges Vermögen, dass ich nie mehr meinen Werkzeugkasten öffnen müsste. Und er meint es wirklich ernst. Wenn wir hier fertig sind und ich ihm die Baupläne meiner Fallen überlasse, gehören sie endgültig ihm.\n\nEhrlich gesagt kommt es mir vor, als würde ich einen Teil meiner Identität aufgeben, aber Mutter braucht das Gold. Ich hasse es, sie so zu sehen. Sie erkennt mich kaum noch. Ihre Krankheit wird immer schlimmer.\n\n* * *\nTag 2\n\nWir haben endlich unser Lager in einem recht ruhigen Teil des östlichen Sonnenwende aufgeschlagen, und doch spukt mir noch immer der Gedanke im Kopf herum, ob ich meinen Teil dieser Abmachung tatsächlich einhalten kann. Nein, mittlerweile bin ich mir sicher.\n\nIch werde morgen die Fallen legen, aber ich habe mich entschieden: Ich werde ihm die Baupläne dafür nicht überlassen. Vater hat mir dabei geholfen, sie zu perfektionieren. Wenn ich eine Falle baue, kommt es mir vor, als wäre er noch bei mir, und Mutter würde ebenfalls nicht wollen, dass ich mein Wissen derart verschachere.\n\nIch werde es Sadryn sagen und ihm weiterhin helfen, diese Jagd erfolgreich zu Ende zu bringen. Ich brauche das Gold. Aber danach werden wir eine neue Abmachung finden müssen.\n\n* * *\nSadryn wurde so wütend, als ich es ihm erzählte. Er drehte komplett durch! Bei der Göttern, er hat auf mich eingestochen! Ich konnte ihm einen Hieb auf die Brust verpassen, der ihn in die Flucht schlug. Ich hätte auf sein Herz zielen sollen.\n\nEs tut so weh. Es hört einfach nicht auf zu bluten. Ich verstecke mich, aber ich höre, wie er nach mir sucht. Das Schreiben fällt mir immer schwerer.\n\nMutter, es tut mir ...",
    ["Monthly report from Dark Adept Bruhlz.\n\nRecent Acquisitions:\n\n57 Stone-Nest Argonians taken from villages\n6 Escaped Stone-Nest Argonians, recaptured\n7 Stirk Fellowship soldiers \n1 Argonian necromancer, imprisoned for betraying the order\n\n<scribbled in a different hand>\nThe shackles need more souls to fully merge Coldharbour into this plane. And the improved devices must be tested. For that, we require more prisoners. If you cannot secure them, I will select volunteers from among the faithful in your nest.\n\nAnd make sure the traitor suffers. Sacrifice her last. Let her see what the flayers do to those she felt obligated to protect.\n\nMannimarco, King of Worms"] = "Monatlicher Bericht des Dunklen Adepten Bruhlz.\n\nNeuzugänge:\n\n57 Steinnest-Argonier aus Dörfern\n6 entkommene Steinnest-Argonier, wieder eingefangen\n7 Soldaten der Stirk-Gefolgschaft\n1 argonische Nekromantin, eingekerkert wegen Verrats am Orden\n\n<in anderer Handschrift dazu gekritzelt>\nDie Ketten brauchen mehr Seelen, um Kalthafen vollständig in diese Ebene zu bringen. Und die verbesserten Geräte müssen erprobt werden. Dafür brauchen wir mehr Gefangene. Wenn Ihr keine besorgen könnt, werde ich Freiwillige aus den Getreuen in Eurem Nest auswählen.\n\nUnd sorgt dafür, dass die Verräterin leidet. Opfert sie zuletzt. Lasst sie mitansehen, was die Schinder mit jenen anstellen, die sie dachte beschützen zu müssen.\n\nMannimarco, König der Würmer",
    ["Hail Mannimarco!\n\nYour humble servant reports that our experiments with the new soul flayers have been a resounding success. We disguised ourselves as merchants and brought one of the single-use flayers into a village near the Xul-Haj necropolis. The foolish lizards did not suspect a thing! We retreated to a safe distance to observe and activated the flayer. It performed as expected, sending out a burst of necrotic energy that killed everyone within the prescribed perimeter, sending their souls to the wraithforge. I will now return to collect the flayer for reconditioning.\n\nMay your work on the great rising swell our ranks with unstoppable undead warriors! May we gain an army of the dead from the depths of Xul-Haj!\n\nYour Servant,\nOverseer Bazgrum"] = "Gepriesen sei Mannimarco!\n\nEuer bescheidener Diener meldet, dass unsere Experimente mit den neuen Seelenschindern ein durchschlagender Erfolg waren. Wir verkleideten uns als Händler und brachten einen der einmal verwendbaren Schinder in ein Dorf bei der Xul-Haj-Nekropole. Die törichten Echsen waren völlig ahnungslos! Wir zogen uns in eine sicher Entfernung zurück, um den Schinder zu aktivieren und zu beobachten. Er funktionierte wie erwartet und erzeugte einen Impuls nekrotischer Energie, der alle im beschriebenen Umfeld tötete und ihre Seelen in die Schreckensschmiede schickte. Ich werde jetzt zum Schinder zurückkehren und ihn zur Neukonditionierung abholen.\n\nMöge Euer Werk in der großen Erweckung unsere Reihen mit unaufhaltsamen untoten Kriegern füllen! Mögen wir aus den Tiefen von Xul Haj eine Armee der Toten gewinnen!\n\nEuer Diener,\nAufseher Bazgrum",
    ["Investigate the Village of Oozt-Tzel"] = "Untersucht das Dorf Oozt-Tzel",
    ["You mentioned the Void. I take it you're here on personal business and want to keep it that way?"] = "Ihr erwähntet die Leere. Dann seid Ihr wohl aus persönlichen Gründen hier und möchtet es auch dabei belassen?",
    ["No. I'm sorry. I was reassigned to Gristmung Hold when they needed more help with the soul flayer experiments. I do not know where they sent Vanus after that.\n\nBut he wrote a note and slipped it to me. Asked me to get it to Gabrielle when I could."] = "Nein. Es tut mir leid. Ich wurde in die Gristmungfeste verlegt, als sie mehr Hilfe bei den Experimenten mit den Seelenschindern brauchten. Ich weiß nicht, wohin sie Vanus danach schickten.\n\nDoch er schrieb eine Notiz und steckte sie mir heimlich zu. Er bat mich, sie zu Gabrielle zu bringen, sobald mir dies möglich war.",
    ["Big, wretched siege weapon. Hits with the very hatred of Coldharbour. Blows against a ship are ruinous, and those against crew are fatal.\n\nNo idea what it would do to Velehk Sain and his lot. But Suraj would love to find out."] = "Große, fiese Belagerungswaffen. Schleudern den Hass von Kalthafen. Treffer an Schiffen sind verheerend, die an der Besatzung sind tödlich.\n\nKeine Ahnung, was sie mit Velehk Sain und seiner Meute anstellen würden. Aber Suraj würde es zu gern herausfinden.",
    ["Sithis worship has been a part of Argonian culture forever, though the Dread Father no longer features prominently in their day-to-day worship. \n\nBut here on Solstice, one warrior in each tribe, the death-dancer, still hews to the old ways."] = "Die Anbetung von Sithis ist seit jeher ein Teil der argonischen Kultur, auch wenn der Schreckensvater kein großer Teil der alltäglichen Verehrung mehr ist.\n\nAber hier auf Sonnenwende pflegt ein Krieger pro Stamm, der Todestänzer, noch immer die alten Traditionen.",
    ["Kauldin studied under her. He was one of the apprentices she took under her wing and trained to be a marine.\n\nBut we saw her working with the cultists. She even struck down most of her apprentices. Kauldin's lucky to have survived."] = "Kauldin lernte bei ihr. Er war einer der Lehrlinge, die sie unter ihre Fittiche nahm und zum Seesoldaten ausbildete.\n\nAber wir haben gesehen, wie sie mit den Kultisten zusammenarbeitet. Sie hat sogar einen Großteil ihrer Lehrlinge niedergemacht. Kauldin hat Glück, überlebt zu haben.",
    ["That tracks. We saw her carrying a staff and heading toward the gathering hall at the center of the lodge. When the cultist with her hurled a bolt of fire, I didn't think. I just leaped in front of Consewen.\n\nShe … she would do the same for me."] = "Das passt. Wir haben sie mit einem Stab auf dem Weg zur Versammlungshalle im Zentrum der Residenz gesehen. Als der Kultist bei ihr einen Feuerblitz schleuderte, habe ich nicht nachgedacht. Ich sprang einfach vor Consewen.\n\nSie ... sie würde dasselbe für mich tun.",
    ["Master Tanertor is alive! That's good to hear!\n\nPlease, activate the portal gate so I can get Latanwen to a healer in Sunport."] = "Meister Tanertor lebt! Das ist gut zu hören!\n\nBitte, aktiviert das Portaltor, damit ich Latanwen in Sonnhafen zu einem Heiler bringen kann.",
    ["I do not like to answer such broad questions with a simple yes or no. First off, I am not Meridia. Her powers are not mine to bestow. But power can be transferred from one receptacle to another.\n\nThe Light of Meridia should be no different."] = "Solch allgemeine Fragen beantworte ich nicht gern mit einem einfachen Ja oder Nein. Ich bin nicht Meridia. Ihre Kräfte kann nicht ich verleihen. Aber Macht kann von einem Behältnis aufs nächste übertragen werden.\n\nDas Licht von Meridia ist da nicht anders.",
    ["I thought I heard shrieking. Didn't want to get my hopes up that it might have been her.\n\nPerhaps it's time I let those old bones go. If you're ready to move on, there's another favor I need to ask of you."] = "Dachte ich mir schon, dass ich etwas kreischen hörte. Wagte aber nicht zu hoffen, dass sie es ist.\n\nVielleicht sollte ich diese alten Knochen gehen lassen. Wenn Ihr bereit seid, hätte ich noch eine Bitte an Euch.",
    ["There are two sides to every story. Long after our ancestors first sealed Mor Naril, they had to fight off Corelanya forays. Elven records of those troubled times reside in the library of the Sea and Sword Lodge.\n\nYou could seek your answers there."] = "Jede Geschichte hat zwei Seiten. Lange nachdem unsere Ahnen Mor Naril zum ersten Mal versiegelten, mussten sie Vorstöße der Corelanyas abwehren. Elfische Aufzeichnungen aus diesen schwierigen Zeiten werden in der Bibliothek der Residenz von Meer und Schwert aufbewahrt.\n\nIhr könntet dort nach Eurer Antwort suchen.",
    ["Hmm … very well. Allowing outsiders to have a look at the restricted parts of our collection is rather against the rules, but under these circumstances? I think it would be warranted.\n\nOne moment. I need to refer to our catalog."] = "Hm ... Nun gut. Außenseitern einen Blick in die geschlossenen Teile der Sammlung zu gewähren, ist zwar deutlich gegen die Regeln, doch unter diesen Umständen? Da halte ich es für angebracht.\n\nEinen Augenblick. Ich muss in unserem Katalog nachschlagen.",
    ["<These crumbling notes are covered in fading Jel glyphs. In the margins, written in Tamrielic, are translation notes left by a Stone-Shaper some centuries ago.>\n\n<Translation> \"The war is won and yet I continue to toil away. Perhaps the others were right. If one wishes to know the color of obsession, you need only look to my scales. At my aching, calloused claws shaped to the handles of my tools. But I do not work without purpose.\n\n\"I see a new hunger growing in the eyes of our leaders. They see my guardians not as protectors, but as weapons. Tools for a war beyond our shores. This is not why I built them. I will now spend my final years locking them away, along with their control stone. The wonders of this temple, once a testament to our courage, are now a trap for those seeking war in times of peace.\"\n\n* * *\n<Translator's Note> So the vault I glimpsed at the temple's center holds not viridian life, but the forms which were shaped from it. The voskrona. It is strange, translating the words of an Argonian as ancient as I feel. How I empathize with his aches as I see a slow, growing harshness to his glyphs. An unevenness that reveals a petrified shoulder. A locked wrist. Ailments that I too massage between quill strokes.\n\nLife-Carver Tzinik-Muz, we are egg-kin more than I could have realized. I do not seek your guardians as tools of war. In truth, I wished for the secrets of their design so I too could shape life from stone. Hubris is the color of my scales.\n\nI wish I could see these protectors first hand, but this old stone-shaper can proceed no farther into these old ruins. I leave my notes to any egg-kin who may follow in my steps. If you seek out Tzinik-Muz's vault, and the voskrona guardians' control stone, you must first release the three counterweights and face the temple's pendulums with courage.\n\nStone-Shaper Jazeez"] = "<Diese zerfallenden Aufzeichnungen sind übersät mit verblichenen Jel-Glyphen. In die Zwischenräume hat vor Jahrhunderten ein Steinformer Übersetzungen ins Tamrielische eingetragen.>\n\n<Übersetzung> „Der Krieg ist gewonnen, und dennoch plage ich mich weiter ab. Vielleicht hatten die anderen recht. Wer die Farbe der Besessenheit sehen möchte, muss nur auf meine Schuppen blicken. Auf meine schmerzenden, mit Schwielen übersäten Klauen, die sich an die Form meiner Werkzeuge angepasst haben. Aber ich arbeite nicht ohne Ziel.\n\nIch sehe einen neuen Hunger in den Augen unserer Anführer wachsen. Sie sehen meine Wächter nicht als Beschützer, sondern als Waffen. Werkzeuge für einen Krieg jenseits unserer Ufer. Doch dafür habe ich sie nicht geschaffen. Ich werde meine letzten Jahre nun damit verbringen, sie wegzusperren, und ebenso ihren Kontrollstein. Die Wunder dieses Tempels, die einst von unserer Tapferkeit berichteten, sind nun eine Falle für jene, die Krieg in Zeiten von Frieden anstreben.“\n\n* * *\n<Anmerkung des Übersetzers> Das Gewölbe, das ich im Zentrum des Tempels erblickte, enthält also kein grünes Leben, sondern die Gestalten, die daraus geformt wurden. Die Voskrona. Es ist merkwürdig, die Worte eines Argoniers zu übersetzen, der so uralt war, wie ich mich fühle. Ich kann anhand der langsam zunehmenden Härte seiner Glyphen seinen Schmerz nachempfinden. Und Ungleichmäßigkeit, die eine versteinerte Schulter verrät. Ein steifes Handgelenk. Gebrechen, die auch ich zwischen Federstrichen wegzumassieren versuche.\n\nLebens-Metz Tzinik-Muz, wir sind Eigeschwister, und zwar mehr, als ich mir je hätte träumen lassen. Ich suche Eure Wächter nicht, weil ich Kriegsgerät in ihnen sehe. In Wahrheit strebe ich nach den Geheimnissen ihrer Entstehung, damit auch ich Leben aus dem Stein formen kann. Hybris hat die Farbe meiner Schuppen.\n\nIch wünschte, ich könnte diese Beschützer mit eigenen Augen sehen, aber dieser alte Steinformer kann nicht weiter in diese zerfallenen Ruinen vordringen. Ich hinterlege meine Aufzeichnungen für Eigeschwister, die vielleicht meinen Spuren folgen. Wenn Ihr Tzinik-Muzs Gewölbe sucht und den Kontrollstein der Voskrona-Wächter, müsst Ihr zuerst drei Gegengewichte entriegeln und Euch den Pendeln des Tempels tapfer stellen.\n\nSteinformer Jazeez",
    ["I couldn't believe it when I heard that this place had ended up in Nirn. I convinced Sirilonwe that a research trip would provide a lot of information on vampires. Things the Mages Guild can use to combat any who posed a danger. This approach worked as I knew it would.\n\n* * *\nThe trip was uneventful and we made camp. I feel a strange sense of purpose? Energy? I am close. I know it. \nWe met another mage, Ormard. He has worked on a vampire compendium for decades, so it's no surprise that he knew of this place. He's a pleasant Nord fellow and even Sirilonwe warmed to him. \n\nOrmard and I have compared notes. His interest seems purely academic and he is eager to get into the place. Sirilonwe is still making some plans, not wanting to rush headlong into danger as she says. Ormard has been generous with the information he has on the Hall. It has sealed doors, different sections. Ormard says there are unique keys or tokens of some sort to open them. \n\n* * *\nOrmard and I decided to do an initial survey into the Hall. I confessed that my real interest was not so much the vampire denizens, but rather the Daedric artifacts rumored to be held within, and that I wanted to confirm that and maybe even bring one back to do my own research. I said Sirilonwe had strong opinions about what she calls relic hunting so I have not told her my true purpose. Ormard understood. He then confessed he found a break in the foundations! A small cave south of our camp. It will allow us to slip quietly into the place, as the main doors appear to be inaccessible after the place fell out of Coldharbour. \n\nWe're doing it. I am close. My heart is racing. Sirilonwe will be furious, but I am sure I can talk her around."] = "Ich konnte es kaum fassen, als ich hörte, dass dieser Ort nun in Nirn ist. Ich versuchte, Sirilonwe davon zu überzeugen, dass eine Forschungsreise uns eine Menge Informationen über Vampire bringen könnte. Informationen, die die Magiergilde im Kampf gegen jene einsetzen kann, die eine Gefahr darstellen. Und ich täuschte mich nicht: Dieser Ansatz hatte Erfolg.\n\n* * *\nDie Reise war ereignislos, und wir schlugen unser Lager auf. Ich spüre ein merkwürdiges Gefühl von Bestimmung? Von Energie? Ich bin nahe dran. Das weiß ich.\nWir trafen einen weiteren Magier, Ormard. Er arbeitet seit Jahrzehnten an einem Vampirkompendium, also ist es wenig verwunderlich, dass er von diesem Ort wusste. Er ist ein angenehmer Nord, und selbst Sirilonwe wurde mit ihm warm.\n\nOrmard und ich haben unsere Aufzeichnungen verglichen. Sein Interesse ist rein akademischer Natur, und er kann es kaum erwarten, diesen Ort endlich zu betreten. Sirilonwe macht noch Pläne; sie möchte sich nicht Hals über Kopf in Gefahr stürzen, sagt sie. Ormard war großzügig mit den Informationen, die er über die Halle hat. Sie hat versiegelte Türen, verschiedene Abschnitte. Laut Ormard gibt es individuelle Schlüssel oder Marken, mit denen man sie öffnen kann.\n\n* * *\nOrmard und ich entschlossen uns, einen ersten Vorstoß in die Halle zu wagen. Ich gab zu, dass mein wahres Interesse nicht so sehr den vampirischen Bewohnern galt, sondern vielmehr den daedrischen Artefakten, die Gerüchten zufolge in den Hallen warten. Dass ich dies überprüfen wolle und vielleicht sogar eines mitnehmen kann, um meine eigene Forschung daran durchzuführen. Wie gesagt hatte Sirilonwe eine eindeutige Meinung zu dem, was sie „Reliktjagd“ nennt, also verschwieg ich ihr meine tatsächlichen Absichten. Ormard verstand mich. Dann gestand er mir, dass er einen Durchbruch im Fundament gefunden hatte! Eine kleine Höhle südlich unseres Lagers. So können wir uns unbemerkt in die Hallen schleichen, da das Hauptportal offenbar unbrauchbar wurde, nachdem der Ort aus Kalthafen heruntergestürzt ist.\n\nWir tun es. Ich bin nahe dran. Mein Herz rast. Sirilonwe wird außer sich sein vor Wut, aber das bekomme ich schon hin.",
    ["The Vos-Toh stone tablets offer a glimpse into Argonian death-dancers' beliefs in ancient times. I find them quite inspiring. They deserve extensive study. There are far more than just these simple words beneath the surface of the carefully carved glyphs.\n\n* * *\nVos-Toh of Song\n\nHail Sithis, the nothing of the Outer Darkness. No gentle truths placate fear. Embrace fear, for it is the song of the blood. We raise our voices to speak the words of the Void, the artistry of the Void, the truth of the Void.\n\n* * *\nVos-Toh of Dance\n\nHail Sithis, the serpent of chaos. Constantly moving. Never still. So we dance a ceaseless promenade. To one day slide and step and bounce joyously into the Void. To enact his will with perfect clarity and one day dance beside the Night Lord himself.\n\n* * *\nVos-Toh of Death\n\nHail Sithis, the ever-changing. What is consumed is restored. This is why we die. To one day soar beyond the reach of sun and stars, to enter the space between. To honor his will. To destroy what was and create what will be."] = "Die Vos-Toh-Steintafeln bieten uns einen Einblick in den Glauben der argonischen Todestänzer in grauer Vorzeit. Ich finde sie recht inspirierend. Sie verdienen es, eingehender studiert zu werden. Hinter den sorgsam gehauenen Glyphen verbirgt sich weit mehr als diese einfachen Worte.\n\n* * *\nVos-Toh des Liedes\n\nGepriesen sei Sithis, das Nichts der Äußeren Dunkelheit. Keine sanften Worte beschwichtigen die Furcht. Nehmt die Furcht an, denn sie ist das Lied des Blutes. Wir erheben unsere Stimmen, um die Worte der Leere zu sprechen, die Kunstfertigkeit der Leere, die Wahrheit der Leere.\n\n* * *\nVos-Toh des Tanzes\n\nGepriesen sei Sithis, die Schlange des Chaos. Stetig in Bewegung. Nie reglos. Und so tanzen wir im unablässigen Wandeln. Bis wir eines Tages abgleiten in unserem Schritt und mit Freuden in die Leere springen. Um seinen Willen mit perfekter Klarheit auszuführen und eines Tages an der Seite des Nachtfürsten selbst zu tanzen.\n\n* * *\nVos-Toh des Todes\n\nGepriesen sei Sithis, der sich stets verändert. Was verschlungen ward, wird wiederhergestellt. Deshalb sterben wir. Um eines Tages jenseits der Reichweite von Sonne und Sternen zu tanzen. Um Raum zwischen ihnen zu betreten. Um seinen Willen zu ehren. Um zu zerstören, was war, und zu erschaffen, was sein wird.",
    ["Tell me then, this Mani-Kai. I see a brittle thing, fresh from her egg. Eager as the lichen that grows wide without first placing roots. Do you trust her? Can she really hear the Hist?"] = "Dann sagt mir, diese Mani-Kai. Ich sehe ein zerbrechliches Ding, frisch aus dem Ei. Eifrig wie der Efeu, der sich weit erstreckt, ohne zuerst Wurzeln zu schlagen. Vertraut Ihr ihr? Kann sie den Hist wirklich hören?",
    ["How lucky are you to have walked through the mud alongside my teacher. You know then that the chimes I carry will help me interpret this tree's song. I only hope it will be enough to prove to these villagers that we are here to help."] = "Welch Glück Ihr habt, an der Seite meines Lehrmeisters durch den Schlamm gezogen zu sein. Dann wisst Ihr, dass das Windspiel, das ich trage, mir beim Deuten des Histliedes helfen wird. Ich hoffe nur, dass das reicht, um diesen Dorfbewohnern zu beweisen, dass wir helfen möchten.",
    ["There's a letter over there from Adrolir. It's addressed to you."] = "Dort drüben ist ein Brief von Adrolir. Er ist an Euch gerichtet.",
    ["Need to get more information from Ormard on these doors. Such elaborate mechanisms. Not mechanical. Not wholly magical. He said that he has a way to get past them, thanks to his various partners within the hall. Well, not partners, exactly. He continues to be a bit cagey with his information thus far.\n\nI hope Sirilonwe manages to catch up eventually. She should be here to write down all my observations."] = "Ormard muss mir mehr über diese Türen erzählen. Welch kunstfertige Mechanismen. Nicht mechanisch. Auch nicht vollständig magisch. Er sagte, er habe eine Möglichkeit, sie zu überwinden, dank seinen verschiedenen Partnern in der Halle. Nun, nicht wirklich Partner. Bisher geizt er weiterhin ein wenig mit seinen Informationen.\n\nIch hoffe, dass Sirilonwe früher oder später zu uns aufschließt. Sie sollte hier sein und all meine Beobachtungen niederschreiben.",
    ["If the journals spoke true, their creators intended for them to act as defenders of their people. Let us hope that we have given the egg-kin of Xor-Hist the edge they need to face the necromancers."] = "Wenn die Tagebücher die Wahrheit sagen, hatten ihr Schöpfer sie als Verteidiger ihres Volkes vorgesehen. Hoffen wir, dass wir den Eigeschwistern von Xor-Hist den Vorteil verschafft haben, den sie gegen die Nekromanten brauchen.",
    ["Here as in Nirn? A whirlpool opened up on the azure seas. Captain One-Eye cackled and sailed us right in. Somehow she knew it would get us out of Coldharbour.\n\nNo one knew it would drop us from the sky. Or that Velehk Sain would dare to follow."] = "Mit „hier“ meint Ihr Nirn? Ein Wirbelbecken öffnete sich im Azurmeer. Kapitän Ein-Auge lachte laut und segelte direkt hinein. Irgendwie wusste sie, dass wir so aus Kalthafen entkommen können.\n\nNiemand ahnte, dass wir vom Himmel fallen werden. Oder dass Velehk Sain es wagen würde, uns zu folgen.",
    ["by Midconjuror Mirmal of the College of Rituals\n\nFew of Sunport's folk venture across the Solstice Range to visit the eastern half of our fair island. Yet this was not always the case. When House Corelanya first settled on these shores, our ancestors looked beyond the mountains and saw a land ripe for settlement. The fact that the Stone-Nest Argonians already lived there did little to deter the interest of proud kinlords and kinladies who desired a realm wide enough to suit their ambitions.\n\nWhen Kinlord Orlemar came to power in 1E 1017, he decided to act upon those ambitions. During his reign, vast tracts of land in eastern Solstice were parceled out to powerful nobles to settle or exploit as they wished. Yet no one seems to have informed the Stone-Nests about the arrangement. Centuries of strife between Elf and Argonian followed from the haughty kinlord's dealings.\n\nNaturally, Orlemar did not forget himself when handing out parcels of eastern Solstice. The kinlord claimed a magnificent estate in the northern part of the island, and named it Vaedinhill. There he commissioned the building of a great manor-house to serve as his summer palace, a luxurious retreat from the cares of the cares of the throne.\n\nThe cost of building Vaedinhill Manor nearly bankrupted the realm. Constructing such an extravagant palace in the wilds of eastern Solstice, far from the resources and workforce of Sunport, proved expensive indeed. But in 1E 1107, Kinlord Orlemar's palace was finally completed, a vision of fair Summerset amid a virgin wilderness. It was not to last.\n\nArgonian resistance to Kinlord Orlemar's policies was growing. While the kinlord enjoyed his palace for a time, travel to and from Vaedinhill became dangerous. Bands of Stone-Nest warriors began to shadow, and sometimes attack, travelers and wagons on the road to Vaedinhill. Orlemar found it increasingly difficult to maintain his court in the east. He did not visit the manor at all in the last ten years of his life, although he was laid to rest there.\n\nWhen open fighting broke out in 1E 1172, Stone-Nest warriors burned down Vaedinhill. During the troubled years that followed, Orlemar's successors could find neither the funds nor the forces needed to rebuild Vaedinhill. By the time Kinlady Torinwe concluded the Peace of Xor-Hist, House Corelanya had no interest in maintaining grand estates east of the mountains.\n\nOne can still visit the ruins of Vaedinhill to this day. Crumbling walls of white stone and weed-choked courtyards attest to the magnificence of Kinlord Orlemar's vision—and his folly."] = "von Mittelbeschwörer Mirmal vom Kolleg der Rituale\n\nNur wenige Bewohner von Sonnhafen reisen über das Sonnenwendgebirge in die Osthälfte unserer schönen Insel. Doch das war nicht immer so. Als Haus Corelanya sich erstmals an diesen Ufern niederließ, blickten unsere Ahnen jenseits der Berge, und sie sahen ein Land, das zu besiedeln sich lohnte. Dass die Steinnest-Argonier bereits dort lebten, tat dem Interesse unserer stolzen Sippenfürsten und Sippenfürstinnen keinen Abbruch. Sie wünschten ein Reich, das ihren großen Ambitionen angemessen war.\n\nAls im Jahr 1Ä 1017 Sippenfürst Orlemar an die Macht kam, entschied er, seinen Ambitionen Taten folgen zu lassen. Während seiner Herrschaft wurden gewaltige Landstriche im östlichen Sonnenwende an mächtige Adlige verteilt, die sich darauf niederlassen oder sie ausbeuten konnten, ganz nach ihren Wünschen. Doch offenbar hatte niemand den Steinnestern davon erzählt. Aus den Machenschaften des überheblichen Sippenfürsten entsprangen Jahrhunderte des Hasses zwischen Elf und Argonier.\n\nNatürlich vergaß Orlemar bei seiner Verteilung des östlichen Sonnenwende auch sich selbst nicht. Der Sippenfürst sicherte sich ein prächtiges Anwesen im nördlichen Teil der Insel und nannte es Vaedinhill. Dort ließ er ein majestätisches Herrenhaus erbauen, das ihm als Sommerpalast dienen sollte, als luxuriöser Rückzugspunkt abseits der Bürde des Throns.\n\nDie Baukosten des Vaedinhill-Herrenhauses trieben das Reich beinahe in den Bankrott. Ein solch extravaganter Palast in der Wildnis des östlichen Sonnenwende, fernab der Rohstoffe und der Arbeiterschaft von Sonnhafen, erwies sich als wahrlich kostspieliges Unterfangen. Aber im Jahr 1Ä 1107 wurde der Bau von Sippenfürst Orlemars Palast endlich abgeschlossen, eine Vision des anmutigen Sommersend inmitten unberührter Wildnis. Doch diese Vision währte nicht lang.\n\nDer argonische Widerstand gegen die Politik von Sippenfürst Orlemar nahm zu. Obgleich der Sippenfürst sich eine Weile an seinem Palast erfreuen konnte, wurde die Reise von und nach Vaedinhill immer gefährlicher. Banden von Steinnest-Kriegern beschatteten Reisende und Wagen auf der Straße nach Vaedinhill und griffen sie mitunter sogar an. Orlemar fiel es zunehmend schwer, seinen Hof im Osten aufrechtzuerhalten. In den letzten zehn Jahren seines Lebens besuchte er das Herrenhaus nicht mehr, obschon er später darin bestattet wurde.\n\nAls es im Jahr 1Ä 1172 zum offenen Konflikt kam, brannten Steinnest-Krieger Vaedinhill nieder. Während der schweren Jahre, die folgten, konnten Orlemars Nachfolger weder die Mittel noch die Kräfte aufbringen, um Vaedinhill wiederaufzubauen. Als Sippenfürstin Torinwe schließlich den Frieden von Xor-Hist schloss, hatte Haus Corelanya kein Interesse mehr daran, prächtige Anwesen östlich der Berge zu unterhalten.\n\nMan kann heute noch die Ruinen von Vaedinhill besuchen. Zerfallende Mauern aus weißem Stein und von Unkraut überwucherte Innenhöfe geben Zeugnis ab über die Pracht von Sippenfürst Orlemars Vision, und seiner Torheit.",
    ["Her Kinlady Torinwe of Corelanya, regarding with her favor the native rulers and tribes of Solstice and anxious to put to rest the strife between all the inhabitants of the island, wishes to secure for all impacted by the unrest peace, security, and good will between Elves and Argonians, which has been thus far exacerbated by the aforementioned conflict. \n\nTo this end she, alongside Tuintirrimo of the Corelanyan Guard and Pamaldawe of the Collegium, invite Mahei-Gei, representative for the Tide-Born of the western shores, and Tlekeus, speaking for the Stone-Nest of the eastern reaches, to concur upon the following articles and conditions. \n\nARTICLE THE FIRST\nAs long as all spoken-for inhabitants of Solstice adhere to the articles laid out in this document, they will lay down their arms against one another and vow to refrain from taking any hostile actions regarding ancestral or recent grievances. \n\nARTICLE THE SECOND\nAs set forth by this assembled congregation, the territories belonging to the Corelanya, Stone-Nest, and Tide-Born are hereby recognized as the sovereign land of the peoples thereof. Corelanya and Argonian alike agree not to encroach on the others' lands or impede them from crossing from one territory to another. Henceforth, no permanent dwellings shall be constructed in another's territory without express and written permission.\n\nARTICLE THE THIRD\nIn times when Solstice is threatened, we will temporarily waive the previous articles for the sake of mutual defense. \n\nWe signatories and assembled attendants, having been made fully aware of the provisions of this treaty, accept and enter into the full spirit of the stated agreement. \n\nCompleted at Xor-Hist in the year 1244 of the First Era."] = "Die hochwohlgeborene Sippenfürstin Torinwe von Corelanya wünscht die einheimischen Herrscher und Stämme von Sonnenwende mit ihrer Gunst zu beglücken und den Zwist zwischen allen Bewohnern der Insel zu beenden. Alle Betroffenen sollen Frieden, Sicherheit und guten Willen zwischen Elfen und Argoniern genießen, was bisher durch den bereits erwähnten Konflikt unmöglich war.\n\nHierzu lädt sie gemeinsam mit Tuintirrimo von der Corelanyaischen Garde und Pamaldawe vom Kollegium als Vertretung der Gezeitengeborenen von der Westküste Mahei-Gei ein und Tlekeus, der für die Steinnester der östlichen Gebiete spricht, die folgenden Paragraphen und Bedingungen zu bestätigen:\n\nPARAGRAPH NUMMER EINS\nSolange alle redlichen Bewohner von Sonnenwende sich an die in diesem Dokument dargelegten Paragraphen halten, werden sie ihre Waffen gegeneinander niederlegen und schwören, von jeglichen durch uralte oder neue Grolle bedingten feindseligen Handlungen abzusehen.\n\nPARAGRAPH NUMMER ZWEI\nWie von diesem versammelten Gremium entschieden, sollen die Territorien, die Corelanya, Steinnestern und Gezeitengeborenen gehören, von nun an als souveränes Land der jeweiligen Völkern anerkannt werden. Corelanya und Argonier werden davon absehen, in das Land des jeweils anderen einzuwirken oder zu verhindern, dass der jeweils andere von einem Territorium in das andere übertritt. Von diesem Tage an sollen im Territorium des jeweils anderen ohne ausdrückliche und schriftliche Genehmigung keine dauerhaften Unterkünfte mehr errichtet werden.\n\nPARAGRAPH NUMMER DREI\nIn Zeiten, in denen Sonnenwende bedroht wird, werden wir die vorstehenden Paragraphen vorübergehend zum Zweck der gemeinsamen Verteidigung aussetzen.\n\nWir Unterzeichnenden sowie die versammelten Teilnehmenden sind sich allesamt der Bedingungen dieses Vertrages vollkommen bewusst, stimmen ihnen hiermit gänzlich im Einklang mit seinen Absichten zu.\n\nVollendet in Xor-Hist im Jahr 1244 der Ersten Ära.",
    ["It's not about falling. It's about getting up once again. And I know you can do that."] = "Es geht nicht ums Fallen. Es geht nicht darum, der Aufgabe nicht gewachsen zu sein, sondern mit der Aufgabe zu wachsen. Und ich weiß, dass Ihr das könnt.",
    ["Has anyone ever told you Stone-Nests that your heads are as hard as rocks?"] = "Hat Euch Steinnestern noch niemand gesagt, dass Eure Köpfe unnachgiebig sind wie Fels?",
    ["Of course. A greataxe. A maul. A greatsword. A spear. A quarterstaff."] = "Natürlich. Die Großaxt. Den Streitkolben. Den Bidenhänder. Den Speer. Den Kampfstab.",
    ["\"Release them, vile fiend!\"\n\nThere it is! Such strength. Such power! I feel like I could punch a horse! Has this always been within me? For better or worse, you've helped unleash a beast. Thank you."] = "„Lasst sie frei, übler Unhold!“\n\nNa bitte! Diese Kraft. Diese Macht! Ich fühle mich, als könnte ich ein Pferd umschlagen! War das schon immer in mir? Ob es der Welt passt oder nicht, Ihr habt eine Bestie in mir entfesselt. Danke.",
    ["Return to Lanullin"] = "Kehrt zu Lanullin zurück",
    ["Deliver Baked Potato to Nenilon"] = "Bringt Nenilon die Ofenkartoffel",
    ["So you readily admit you were manipulated? How easily a little stone bends to the whims of wind and rain. You've wasted enough of my time. As the village's death-dancer, it is my duty to strike you down. Ready yourself."] = "Ihr gebt also offen zu, dass Ihr manipuliert wurdet? Wie einfach ein kleiner Stein sich doch den Launen von Wind und Regen hingibt. Ihr habt genug meiner Zeit vergeudet. Als Todestänzer dieses Dorfes ist es meine Pflicht, Euch niederzustrecken. Macht Euch bereit.",
    ["Deliver Banana Surprise to Geraldrim"] = "Bringt Geraldrim die Bananenüberraschung",
    ["Deliver Carrot Soup to Teliwe"] = "Bringt Teliwe die Karottensuppe",
    ["Craft Banana Surprise"] = "Bereitet die Bananenüberraschung zu",
    ["Craft Carrot Soup"] = "Bereitet die Karottensuppe zu",
    ["Craft Baked Potato"] = "Bereitet die Ofenkartoffel zu",
    ["You need to gain Prince Naemon's trust, too. I would do it myself, but he knows me too well. \n\nHis chambers are through the door to our left. Now that I'm in the citadel, I can help with whatever task he gives you. So find me when you're done."] = "Ihr müsst auch das Vertrauen von Prinz Naemon gewinnen. Ich würde es selbst tun, aber er kennt mich zu gut.\n\nSeine Gemächer sind hinter der Tür zu Eurer Linken. Nun da ich in der Zitadelle bin, kann ich bei der Aufgabe helfen, die er Euch erteilt. Kommt zu mir, wenn Ihr fertig seid.",
    ["And how funny is it that the roots of their Hist tree forced them to abandon this temple. There is poetry to that, I am certain of it, but I have not an artist's patience."] = "Schon witzig, dass die Wurzeln ihres Histbaums sie zwangen, diesen Tempel zu verlassen. Da steckt Poesie drin, aber mir fehlt die Geduld eines Künstlers.",
    ["You must be Sirilonwe. The scout Mihnassi told me you lost your friend near the Ashbound Hall."] = "Ihr müsst Sirilonwe sein. Die Späherin Mihinassi meinte, Ihr hättet Euren Freund bei der Aschgebundenen Halle verloren.",
    ["Soon after the Wall fell, a mage named Ormard came to us. He'd seen the Hall and offered to guide us here. Now I wake up and they're both gone. Come, I'll pay you to escort me while I find Terinvel. The vampires may no longer be securely locked away."] = "Kurz nachdem die Mauer fiel, kam ein Magier namens Ormard zu uns. Er hatte die Halle gesehen und bot an, uns herzuführen.\n\nUnd nun wache ich auf und beide sind weg. Kommt, ich bezahle Euch dafür, dass Ihr mich begleitet, während ich nach Terinvel suche. Gut möglich, dass die Vampire nicht mehr hinter Schloss und Riegel sind.",
    ["As I understand it, the Stone-Nest Argonians had numerous encounters with the Daedra when they first arrived on the island. After capturing and guarding the relic for generations, they gave it to us to protect. We must retrieve it."] = "Soweit ich es verstanden habe, hatten die Steinnester zahlreiche Begegnungen mit Daedra, als sie zum ersten Mal auf die Insel kamen. Sie erbeuteten das Relikt und bewachten es über Generationen, sie gaben es uns, damit wir es beschützen. Wir müssen es bergen.",
    ["Return to Tibarr"] = "Kehrt zu Tibarr zurück",
    ["Give the Coin to the Beggar"] = "Gebt die Münze dem Bettler",
    ["Steal a Coin from the Dragon's Hoard"] = "Stehlt eine Münze aus dem Drachenhort",
    ["For now, I'll rest. But it's likely Fenworine reported to some bigger Worm Cult nest. My plan is to meet Master Tanertor with an idea I had to bury them for good.\n\nAnd I'll do it with or without his help."] = "Fürs Erste werde ich mich ausruhen. Aber wahrscheinlich erstattete Fenworine einem größeren Wurmkult-Nest Meldung. Ich plane, Meister Tanertor eine Idee zu unterbreiten, die ihnen ein für allemal ein Ende machen soll.\n\nUnd ich tue es mit oder ohne seine Hilfe.",
    ["Tell me more about Velehk Sain."] = "Erzählt mir mehr über Velehk Sain.",
    ["Well, we're a long way from Alten Corimont, aren't we, pirate?\n\nAh, seems so long ago. Can't even remember the sounds and smells of the swamp. Sight's still burning with those endless waves of azure plasm. But it's good to be back in my home plane."] = "Nun, wir sind weit weg von Alten Corimont, nicht wahr, <<player{Pirat/Piratin}>>?\n\nDas scheint mir so lange her. Kann mich nicht einmal mehr an die Klänge und Gerüche dieses Sumpfes erinnern. Meine Augen brennen noch von den endlosen Wellen azurblauen Plasmas. Aber es ist schön, wieder auf meiner Heimatebene zu sein.",
    ["Hunt Down the Dakoi"] = "Macht Jagd auf den Dakoi",
    ["There was. Celbrim. We were all with Master Rolmedil when the attack happened. He went to go help others after the portal didn't open. I chose to stay and protect Rolmedil, but ….\n\nI was just as scared, too."] = "Ja, das war Celbrim. Wir waren alle bei Meister Rolmedil, als der Angriff begann. Er ging los, um den anderen zu helfen, nachdem sich das Portal nicht öffnete. Ich entschied mich, zu bleiben und Rolmedil zu schützen, aber ...\n\nIch hatte genauso viel Angst.",
    ["You had no qualms about ending me. Prove to me that you can be just as ruthless toward this spy as you were toward me. Take the Eye to the room upstairs. No need to make a mess here.\n\nBring me proof when she's dead."] = "Ihr hattet keine Skrupel, als es um meinen Tod ging. Beweist mir, dass Ihr dieser Spionin gegenüber so rücksichtslos sein könnt, wie Ihr es mir gegenüber wart. Bringt das Auge die Treppe hinauf. Hier unten soll es sauber bleiben.\n\nBringt mir einen Beweis, sobald sie tot ist.",
    ["Thank you. I'm certain he would rather fling himself into the forge than open up to one of us. I'll try and mend things with Alma. We should've listened to her like you did."] = "Danke. Er würde sich vermutlich lieber in die Esse werfen, als sich einem von uns zu öffnen. Ich versuche, die Dinge mit Alma ins Reine zu bringen. Wir hätten ihr zuhören sollen, wie Ihr es getan habt.",
    ["Track the Dakoi"] = "Spürt den Dakoi auf",
    ["Confront the Dakoi"] = "Stellt den Dakoi",
    ["Return to Yesei"] = "Kehrt zu Yesei zurück",
    ["Assist in Sculpting the Mudman"] = "Helft beim Formen des Schlammkerls",
    ["Gather Mud"] = "Sammelt Schlamm",
    ["Return to Dailonda"] = "Kehrt zu Dailonda zurück",
    ["Smear Mud on the Mudman"] = "Schmiert Schlamm auf den Schlammkerl",
    ["Prove Your Strength"] = "Beweist Eure Stärke",
    ["Take Hammer"] = "Nehmt den Hammer",
    ["Return to Mahagog"] = "Kehrt zu Mahagog zurück",
    ["Break the Boulder"] = "Zerschlagt den Brocken",
    ["Gather Honeycomb for Garth"] = "Sammelt Honigwaben für Garth",
    ["Gather Honeycomb"] = "Sammelt Honigwaben",
    ["Return to Garth"] = "Kehrt zu Garth zurück",
    ["Place the Honeycomb on the Feeding Stone"] = "Legt die Honigwabe auf den Futterstein",
    ["Perform the Ritual of Anseilak"] = "Führt das Ritual namens Anseilak durch",
    ["Gather Seawater"] = "Sammelt Meerwasser",
    ["Travel to Motalion Necropolis"] = "Reist zur Nekropole Motalion",
    ["Complete the Ritual of Anseilak"] = "Vollendet das Ritual namens Anseilak",
    ["You didn't know. I suspect the Dark Elf was clueless, too. Ormard was a vampire imprisoned here. Before we fell, that is.\n\nBlind wandering won't help save the mortal. Go south, look for other brightly lit rooms. You'll find a map on the wall in one."] = "Ihr wusstet es nicht. Und der Dunkelelf war vermutlich auch ahnungslos. Ormard war ein Vampir, der hier eingesperrt war. Also bevor wir fielen.\n\nBlindes Herumirren wird den Sterblichen nicht retten. Geht nach Süden, sucht nach anderen hell erleuchteten Räumen. In einem findet Ihr eine Karte an der Wand.",
    ["We can hope. Though my suspicions grow the deeper we get inside this prison. Who left these Aspects around for us to easily find? And why was Terinvel so eager to rush in without me?\n\nAnd finally, why am I friends with such an inconsiderate person?"] = "Wir können hoffen. Obwohl mein Argwohn wächst, je tiefer wir in dieses Gefängnis vordringen. Wer hat diese Aspekte hinterlassen, damit wir sie so einfach finden? Und warum hatte Terinvel es so eilig, ohne mich aufzubrechen?\n\nUnd zuletzt, warum bin ich mit einer derart unbedachten Person befreundet?",
    ["I'll answer any questions, if you spare a potion or spell to aid me. \n\nYes, Ormard and a Dark Elf came through here. They did not notice me. They left in the direction of the courtyard."] = "Ich beantworte Eure Fragen, wenn Ihr mir mit Trank oder Zauber helft.\n\nJa, Ormard und der Dunkelelf kamen hier vorbei. Sie bemerkten mich nicht. Sie gingen in Richtung Innenhof.",
    ["Thank you, stranger. I just want to leave this place. \n\nI had a family once, outside. I want to tell them what happened to me, if they're still alive."] = "Danke, <<player{Fremder/Fremde}>>. Ich will hier einfach nur weg.\n\nEinst hatte ich eine Familie, dort draußen. Ich möchte ihr erzählen, was mir widerfahren ist, wenn sie noch am Leben ist.",
    ["Talk to the Lone Traveler"] = "Sprecht mit der Person auf einer einsamen Reise",
    ["Fair warning—take even a sip and this partnership ends here and now. Bloodmite doesn't drink my blood, but he can find me just by taking a whiff of it. \n\nStrangely, it even helps relax him when he gets anxious."] = "Ich muss Euch warnen: Ein Schluck, und unsere Partnerschaft endet hier und jetzt. Blutzwerg trinkt mein Blut nicht, aber er findet mich, wenn er es auch nur kurz riecht.\n\nMerkwürdigerweise beruhigt ihn der Geruch sogar, wenn er aufgeregt ist.",
    ["Talk to the Hermit"] = "Sprecht mit dem Einsiedler",
    ["I don't know. Such new feelings. Urges to dominate. Perhaps I'll take control of the University. Make all those pitiful academics praise me.\n\nYou should talk to Sirilonwe. I feel powerful thirst coming on."] = "Ich weiß es nicht. Ganz neue Gefühle. Der Drang zu unterwerfen. Vielleicht übernehme ich die Kontrolle über die Universität. Damit all diese erbärmlichen Akademiker mich preisen müssen.\n\nIhr solltet mit Sirilonwe sprechen. Ich spüre einen enormen Durst in mir aufsteigen.",
    ["Heh. Been around my crew so long I forgot it might unsettle folk.\n\nIt's a curse. One I took to save the souls of the Lost Fleet, press-ganged past death to serve in Coldharbour. Now, it's just who I am. No thought of changing back."] = "Ha. Hab so lange niemanden außer meiner Mannschaft gesehen, dass ich vergessen habe, wie beunruhigend das wirken kann.\n\nDas ist ein Fluch. Einen, den ich auf mich nahm, um die Seelen der Verlorenen Flotte zu retten, die nach dem Tod in Kalthafen dienen mussten. Nun ist es einfach das, was ich bin. Ich will es gar nicht rückgängig machen.",
    ["Dosu and I disagree on everything. Always have. But recently, we found something we agree on. Our feelings for one another.\n\nBut in how to consecrate this bond, we clearly disagree. Which courting custom would you find more meaningful, mainlander?"] = "Dosu und ich sind nie einer Meinung. Und sind es auch nie gewesen. Aber in letzter Zeit haben wir etwas gefunden, bei dem wir uns einig sind. Unseren Gefühlen füreinander.\n\nAber wie wir diese Verbindung besiegeln sollen, darüber sind wir uns eindeutig uneinig. Welchen Bindungsbrauch haltet Ihr für bedeutungsvoller, <<player{Festländer/Festländerin}>>?",
    ["Well, yes … it all happened so fast! With her dying breath, brave Golvyni threw herself back into the fray to save me. I … I am not worthy of such a noble deed … but I shall try to be."] = "Nun, ja ... Es ging alles so schnell! Mit ihrem letzten Atemzug warf sich die tapfere Golvyni zurück ins Gefecht, um mich zu retten. Ich ... Ich bin eine solch edle Tat nicht wert ... Aber ich werde versuchen, mich ihrer würdig zu erweisen.",
    ["How long have you and Golvyni worked together?"] = "Wie lange habt Ihr mit Golvyni zusammengearbeitet?",
    ["Oh, where has this day gone? Speaking of my business, I really must be getting back to it now.\n\nFriend, Golvyni is at peace, you have your gold. Let it go. I have bear-lizards to skin and an ailing mother to visit."] = "Oh, wo ist dieser Tag nur hin? Apropos Geschäft, ich muss jetzt weitermachen.\n\n<<player{Mein Freund/Meine Freundin}>>, Golvyni ruht in Frieden, Ihr habt Euer Gold. Lasst es gut sein. Ich muss Schuppenbären häuten und eine kranke Mutter besuchen.",
    ["I was inspired enough by Dullard and his crew to write an epic poem based on their adventures.\n\nWhile doing a reading just now, he felt the need to interrupt and take issues with my creative liberties regarding his selection of bedfellows."] = "Ich war so inspiriert von der Dumpfbacke und seiner Mannschaft, dass ich ein episches Gedicht aus ihren Abenteuern machte.\n\nWährend meiner Lesung fühlte er den Drang, mich zu unterbrechen und sich über meine kreativen Freiheiten bezüglich seiner Auswahl an Bettgefährten zu echauffieren.",
    ["The words of the dead? Really? You're going to believe scribbles in a journal instead of a hunter with an impeccable reputation? No, I fail to see how I deceived you. I only asked for help.\n\nBut you just wanted to be difficult …."] = "Die Worte der Toten? Wirklich? Ihr glaubt Gekritzel in einem Tagebuch mehr als einem Jäger mit tadellosem Ruf? Nein, ich wüsste nicht, wie ich Euch getäuscht hätte. Ich habe lediglich um Hilfe gebeten.\n\nAber Ihr musstet ja unbedingt schwierig sein ...",
    ["Gather Bait"] = "Sammelt Köder",
    ["Are you afraid? Don't be. The cowardly are better to us dead than alive, and I will not hesitate to add your life to our power. \n\nSteel yourself. Soon, we rid this fortress of Naemon's presence!"] = "Fürchtet Ihr Euch? Tut das nicht. Die Feigen nutzen uns tot mehr als lebendig, und ich werde nicht zögern, unsere Macht um Euer Leben zu bereichern.\n\nStählt Euch. Bald schon werden wir Naemons Gegenwart von dieser Festung tilgen!",
    ["Just one, but it requires a favor. I know, you've done plenty already. But could you find a way in, fix the platforms, maybe dispel a few wards? Meridia does love her magic traps! Then we can head inside.\n\nEasy stuff. You got this, right?"] = "Nur eine, aber die erfordert einen Gefallen. Ich weiß, dass Ihr schon reichlich getan habt. Aber könntet Ihr einen Weg hinein suchen, die Plattformen reparieren und vielleicht ein paar Schutzzauber bannen? Meridia liebt ihre magischen Fallen! Dann können wir rein.\n\nGanz leicht. Ihr schafft das, oder?",
    ["You were there? Perhaps you met Er-Jaseen. Crown and beard of black spines. Swishing tail. A kindness in his eyes."] = "Ihr wart dort? Vielleicht habt Ihr Er-Jaseen getroffen. Krone und Bart aus schwarzen Schuppen. Nervöser Schwanz. Gütige Augen.",
    ["Er-Jaseen. He helped Argie escape the Wailing Prison. I meant for him to escape with me, but he stayed behind to help the others. \n\nThere were so many others. I don't know if he escaped. I should never have let him stay behind."] = "Er-Jaseen. Er half Argie bei der Flucht aus dem Wehklagenden Kerker. Ich wollte, dass er mit mir flieht, aber er blieb, um den anderen zu helfen.\n\nDa waren so viele andere. Ich weiß nicht, ob er entkommen ist. Ich hätte ihn nie zurücklassen dürfen.",
    ["Walked right into that one, didn't I?\n\nIf only Salvus was here. You'd have him in stitches. No mirrors on the Spriggan. Heh."] = "Der musste ja kommen, nicht wahr?\n\nWäre doch Salvus hier. Der würde sich schieflachen. Keine Spiegel auf der Zweigling. Ha.",
    ["Find the Oblivion Boulder"] = "Sucht den Felsen aus dem Reich des Vergessens",
    ["Without a single one of our crew seeing you? Hmm. Maybe you are the right sort to take out that observer.\n\nTry not to disappoint me, all right?"] = "Ohne dass Euch unsere Mannschaft gesehen hat? Hmm. Vielleicht könnt Ihr es ja wirklich mit diesem Beobachter aufnehmen.\n\nEnttäuscht mich bitte nicht, ja?",
    ["Remember Camlorn. Your dad. Alinon. The people there."] = "Erinnert Euch an Camlorn. Euren Vater. Alinon. Die Leute dort.",
    ["Remember Shornhelm. Sneaking into Northpoint. Your … antics."] = "Erinnert Euch an Schornhelm. Das Schleichen nach Nordspitz. Eure ... Mätzchen.",
    ["Remember Coldharbour. How we fought alongside King Dynar. How we stopped Molag Bal."] = "Erinnert Euch an Kalthafen. Wie wir an König Dynars Seite kämpften. Wie wir Molag Bal aufgehalten haben.",
    ["I have gone to great lengths to define my authority and the boundaries of the prince's. No one will confuse them again.\n\nIf there are any issues, come to me or one of my aides. We will be more than pleased to clarify who is in charge here."] = "Ich habe ausführlich meine Befehlsgewalt und die Grenzen der des Prinzen dargelegt. Von nun an weiß jeder Bescheid.\n\nFalls es Probleme gibt, kommt zu mir oder einem meiner Gehilfen. Wir stellen nur zu gern klar, wer hier das Sagen hat.",
    ["I am, of course, limited by the bargains I strike with prevailing Princes, but yes. I am a Daedra with many forms. But I do not use this gift to seek power.\n\nOnce I have experienced all Oblivion has to offer, I will finally know who I am."] = "Ich bin natürlich eingeschränkt durch meine Abmachungen mit den jeweiligen Fürsten, aber ja. Ich bin ein Daedra mit vielen Gestalten. Aber ich nutze diese Gabe nicht, um an Macht zu kommen.\n\nWenn ich alles erlebt habe, was das Reich des Vergessens zu bieten hat, werde ich endlich wissen, wer ich bin.",
    ["I can spare a few moments before I resume my preparations to return to the mainland. You've more than earned the right to ask questions, champion."] = "Ich kann ein paar Augenblicke erübrigen, bevor ich meine Vorbereitung für den Aufbruch zum Festland fortsetzen muss. Ihr habt Euch das Recht mehr als verdient, Fragen zu stellen, Champion.",
    ["Why would Molag Bal make vampires fight each other?"] = "Warum sollte Molag Bal Vampire zwingen, gegeneinander zu kämpfen?",
    ["Looking for inspiration! I heard all about the goings-on here and I tried to get here as fast as I could.\n\nSeems like most of the good stuff happened without me here to witness. I'm trying to get what information I can so the trip isn't a total loss."] = "Ich suche nach Inspiration! Habe gehört, was hier alles so vor sich geht, und brach so schnell es ging auf.\n\nOffenbar ist das Beste schon passiert, ohne dass ich es bezeugen konnte. Ich versuche nun, möglichst viele Informationen darüber zu sammeln, damit die Reise nicht völlig vergebens war.",
    ["As vampires age, they gain strength. Physically and magically. And coming here breaks your morality after a while. The kind don't grow old.\n\nElder prisoners force the young to protect them. At threat of exsanguination."] = "Wenn Vampire altern, werden sie stärker. Körperlich und magisch. Und wer hierherkommt, verliert mit der Zeit jede Moral. Die Gütigen werden nicht alt.\n\nÄltere Gefangene zwingen die jungen, sie zu beschützen. Indem sie ihnen mit Blutentleerung drohen.",
    ["As good as I can be after whatever that was in the temple. Did Vanus fill you in? I tried to avoid him, but he's surprisingly limber for a centuries old mage.\n\nBut we're not here to talk about Vanus. Unless you … want to talk about Vanus?"] = "So gut es mir gehen kann, nach dem, was im Tempel geschehen ist. Hat Vanus Euch auf Stand gebracht? Ich versuchte, ihm aus dem Weg zu gehen, aber er ist erstaunlich beweglich für einen Jahrhunderte alten Magier.\n\nAber wird sind nicht hier, um über Vanus zu sprechen. Außer Ihr ... wollt über Vanus sprechen?",
    ["Observe Sirilonwe's Magic"] = "Beobachtet Sirilonwes Magie",
    ["Search the Broken Walkway"] = "Durchsucht den zerbrochenen Gang",
    ["Perform a Dance in the Mud"] = "Vollführt einen Tanz im Schlamm",
    ["Use any Musical Emote"] = "Verwendet eine Musik-Aktion",
    ["Player Logged Out"] = "Spieler hat sich ausgeloggt",
    ["Player Died"] = "Spieler starb",
    ["Notes written by Vanus Galerion to Gabrielle and smuggled out of his prison by Baar-Jasa."] = "Notizen, die von Vanus Galerion an Gabrielle geschrieben und von Baar-Jasa aus dessen Gefängnis geschmuggelt wurden.",
    ["Not precisely, but they know to head to the portal gates in emergencies. However, they need a keystone to activate them and return to Sunport.\n\nTake my keystone. Activate the portals and save my apprentices. I promise to reward you for your efforts."] = "Nicht genau, aber sie wissen, dass sie in Notfällen zu den Portaltoren gehen sollen. Sie brauchen jedoch einen Schlüsselstein, um sie zu aktiveren und nach Sonnhafen zurückzukehren.\n\nNehmt meinen Schlüsselstein. Aktiviert die Portale und rettet meine Lehrlinge. Ich verspreche, Eure Mühen zu belohnen.",
    ["Captain One-Eye. She'll know what to do. Help us, and I'll make sure she cuts you in for a share of our plunder.\n\nThe ships came down by those cliffs to the north. I think, if the captain made it, that is where she'll rally the crew."] = "Kapitän Ein-Auge. Sie wird wissen, was zu tun ist. Helft uns, dann sorge ich dafür, dass Ihr einen Teil unserer Beute abbekommt.\n\nDie Schiffe landeten bei den Klippen im Norden. Glaube ich zumindest. Wenn der Kapitän es überlebt hat, wird sie dort die Mannschaft versammeln.",
    ["You can't find anyone to help you out?"] = "Ihr findet niemanden, der Euch hilft?",
    ["I'll help. What exactly do you need me to do?"] = "Ich werde helfen. Was genau soll ich für Euch tun?",
    ["You made all this food for someone else?"] = "Ihr habt all dieses Essen für jemand anderen gemacht?",
    ["A lot of someones, actually. It's an offering for elders in our community. A chance to pay them back for years of wisdom this New Life, but I'm struggling to find anyone to help me with the final preparations."] = "Genau genommen für viele andere Leute. Das ist eine Gabe für die Ältesten unserer Gemeinschaft. Eine Gelegenheit, ihnen zum Neujahrsfest für die Jahre der Weisheit zu danken, aber ich tue mich schwer, Hilfe bei den abschließenden Vorbereitungen zu finden.",
    ["Everyone's busy with something, from the Three Banners War to a knotted ball of their own problems. And some simply don't care.\n\nSince you seem even the least bit interested, would you be willing to help me? For New Life, and for pay, of course."] = "Jeder hat irgendwie zu tun, vom Krieg der Drei Banner bis zu einem verhedderten Knäuel eigener Probleme. Und einigen ist es schlichtweg egal.\n\nDa Ihr zumindest ansatzweise Interesse zeigt: Könntet Ihr mir vielleicht helfen? Fürs Neujahrsfest, und natürlich gegen Bezahlung.",
    ["A little help for New Life would be appreciated …."] = "Ein wenig Hilfe zum Neujahrsfest wäre gern gesehen ...",
    ["A coin swiped from the hoard of Rawl'kha's Dragon as part of the New Life Festival."] = "Eine Münze, die als Teil des Neujahrsfests aus dem Hort des Drachen von Knurr'kha entwendet wurde.",
    ["Dragon's Coin"] = "Münze des Drachen^f",
    ["Tricky in what way?"] = "Inwiefern knifflig?",
    ["All right. Where can I find the Dragon?"] = "Nun gut. Wo finde ich den Drachen?",
    ["Rawl'kha's Dragon?"] = "Der Drache von Knurr'kha?",
    ["Tibarr apologizes. This one did not mean to alarm. We are in no danger. It is our New Life tradition to steal the Dragon's treasure and distribute it to the needy. Tibarr always organizes it!\n\nHowever, this season's challenge has been … tricky."] = "Tibarr entschuldigt sich. Dieser wollte Euch nicht beunruhigen. Wir sind nicht in Gefahr. Es ist unsere Neujahrsfest-Tradition, den Drachenschatz zu stehlen und unter den Bedürftigen zu verteilen. Tibarr ehrt diese Tradition stets!\n\nAllerdings ist es zu diesen Feiertagen etwas ... knifflig.",
    ["Now, that would spoil the fun! This New Life tradition seeks to help us sharpen both our minds and our claws. Will you try to abscond with the Dragon's hoard?\n\nTibarr promises a portion of the gold will be yours to keep!"] = "Na, ich will Euch doch die Überraschung nicht verderben! Diese Neujahrstradition soll uns helfen, den Geist und die Krallen zu schärfen. Werdet Ihr versuchen, den Drachenhort zu rauben?\n\nTibarr verspricht Euch, dass Ihr einen Teil des Goldes behalten dürft!",
    ["Who will face Rawl'kha's Dragon for New Life?"] = "Wer stellt sich zum Neujahrsfest Knurr'khas Drachen?",
    ["Fresh mud collected for Dailonda's Mudman."] = "Frischer Schlamm, der für Dailondas Schlammkerl gesammelt wurde.",
    ["Mudman Mud"] = "Schlammkerlschlamm^m",
    ["What's making it so difficult?"] = "Was macht es denn so schwierig?",
    ["All right. Where can I find the Dakoi?"] = "In Ordnung. Wo finde ich den Dakoi?",
    ["Who's Dakoi?"] = "Wer ist Dakoi?",
    ["Not a who. A what! Dakoi is a very special, sly … fish. Every New Life season, it greets our waters. It's said good fortune and growth comes to those who feast on this particular fish.\n\nBut, lately, it's proving difficult to catch."] = "Kein Wer! Ein Was! Dakoi ist ein höchst besonderer, schlauer ... Fisch. Zu jedem Neujahrsfest begrüßt er unsere Gewässer. Angeblich bringt es Glück und Wachstum, diesen Fisch zu essen.\n\nAber in letzter Zeit ist es sehr schwer geworden, ihn zu fangen.",
    ["The fish has more tricks than a New Life Festival performer! I promised to reel it in for tonight's feast, but the Dakoi …. I refuse to be embarrassed any further!\n\nHunt the Dakoi for me, and I guarantee you'll get more than just good fortune."] = "Der Fisch hat mehr Tricks auf Lager als ein Neujahrsfest-Gaukler! Ich versprach, ihn für das heutige Festmahl zu fangen, aber der Dakoi ... Ich weigere mich, mich weiter zu blamieren!\n\nJagt den Dakoi für mich, dann garantiere ich Euch, dass Ihr mehr bekommt als nur Glück für die Zukunft.",
    ["That clever little Dakoi can't elude me forever."] = "Dieser schlaue kleine Dakoi kann mich nicht ewig am Schwanz herumführen.",
    ["Forged by Orsimer Orcs to break boulders for Betnikh's Boon in the New Life Festival."] = "Geschmiedet von Orsimer-Orks, um Felsen für Betnikhs Segen beim Neujahrsfest zu zerschlagen.",
    ["Where are your kin?"] = "Wo ist Eure Familie?",
    ["All right. What kind of mud do you need?"] = "Nun gut. Welche Art von Schlamm braucht Ihr?",
    ["What kind of blessing?"] = "Was für ein Segen?",
    ["Orsimer Hammer"] = "Orsimer-Hammer^m",
    ["One only available during New Life. The Mudman is an effigy my kin and I construct to bless the new year with fertile growth across all of Tamriel.\n\nAnd … now I must do it without them."] = "Einen, den es nur beim Neujahrsfest gibt. Der Schlammkerl ist ein Abbild, das meine Familie und ich bauen, um ganz Tamriel im neuen Jahr mit Fruchtbarkeit zu segnen.\n\nUnd nun ... muss ich es ohne die Meinen tun.",
    ["Gone to spread their roots beyond Grahtwood. My home is here with my followers, but with our numbers reduced, we struggle to complete the Mudman.\n\nI believe your path through the Green has led you here. Help us gather mud and you'll be rewarded."] = "Sie sind fort, breiten ihre Wurzeln jenseits von Grahtwald aus. Mein Zuhause ist hier bei meinen Anhängern, aber da wir nun weniger sind, tun wir uns schwer, den Schlammkerl fertigzustellen.\n\nIch glaube, dass Euer Weg durchs Grün Euch hierhergeführt hat. Helft uns, Schlamm zu sammeln, dann werdet Ihr belohnt.",
    ["Let our prayers bring the Mudman to life!"] = "Mögen unsere Gebete den Schlammkerl zum Leben erwecken!",
    ["A sweet and succulent honeycomb. Surely this will lighten the mood of the hermit's bear, Garth."] = "Eine süße Wabe, die vor Honig trieft. Dies wird die Laune von Garth, dem Bären des Einsiedlers, sicher aufheitern.",
    ["Succulent Honeycomb"] = "triefende Honigwabe^f",
    ["You want me to smash a boulder?"] = "Ich soll einen Felsbrocken zerschmettern?",
    ["I accept your challenge. What kind of boulder do you have in mind?"] = "Ich nehme Eure Herausforderung an. An welche Art Felsbrocken habt Ihr gedacht?",
    ["What sort of competition?"] = "Was für ein Wettstreit denn?",
    ["Just the best New Life has to offer! We haul in big boulders and smash them. Whoever breaks a boulder into the smallest bits with one strike claims a boon of good health until the next New Life.\n\nAnd with bragging rights, of course."] = "Der beste, den das Neujahrsfest zu bieten hat! Wir schleppen große Felsbrocken an und zerschlagen sie. Wer einen Felsen mit einem Schlag in die kleinsten Teile zerdeppert, genießt bis zum nächsten Neujahrsfest gesegnete Gesundheit.\n\nUnd darf natürlich damit prahlen.",
    ["Not just any boulder! Let's make it interesting and find one that's truly worthy of Betnikh's Boon! Something none of these losers could ever hope to chip or crack. I'll even throw in something extra for the winner. \n\nSo, friend, what do you say?"] = "Nicht irgendeinen Felsbrocken! Machen wir es interessant; suchen wir einen, der Betnikhs Segen würdig ist! Ein Prachtstück, das keiner dieser Verlierer auch nur ankratzen könnte. Ich lege bei einem Sieg sogar noch etwas obendrauf.\n\nAlso, <<player{Freund/Freundin}>>, was sagt Ihr?",
    ["Can no one provide a proper challenge this New Life?"] = "Bietet zu diesem Neujahrsfest denn niemand eine richtige Herausforderung?",
    ["Why is Garth in a bad mood?"] = "Warum hat Garth schlechte Laune?",
    ["All right. Where can I find some honeycomb?"] = "In Ordnung. Woher bekomme ich Honigwaben?",
    ["Garth wants to eat Tamriel?"] = "Garth möchte Tamriel auffressen?",
    ["Eat, destroy, same difference. The Skaals in the village don't believe it, but Garth has a piece of the All-Maker in him. And it's his jolly mood during New Life that determines Tamriel's fate for the coming year!\n\nRight now, it's not looking good."] = "Auffressen, zerstören, was auch immer. Auch wenn die Skaal im Dorf es nicht glauben, wohnt Garth doch ein Stück des Allschöpfers inne. Und seine gute Laune zum Neujahrsfest bestimmt Tamriels Schicksal für das kommende Jahr!\n\nIm Moment sieht es nicht gut aus.",
    ["Ask the fool in his belly the next time you meet him. At least he was calm while I juggled and … wait.\n\nHoneycomb! That will brighten Garth's mood! Bring him some while I keep juggling and we may just save Tamriel and New Life yet!"] = "Fragt den Narren in seinem Bauch, wenn Ihr ihn das nächste Mal trefft. Zumindest war er ruhig, während ich jonglierte und ... Moment.\n\nHonigwaben! Das wird Garths Stimmung aufhellen! Bringt ihm welche, während ich weiter jongliere. Vielleicht können wir ja Tamriel und das Neujahrsfest noch retten!",
    ["What's wrong, Garth? My juggling used to soothe you."] = "Was ist los, Garth? Normalerweise beruhigt es dich doch, wenn ich jongliere.",
    ["Despite its seemingly ancient make, this water skin shows no signs of wear and tear."] = "Obwohl er von seiner Machart her uralt sein muss, zeigt dieser Trinkschlauch keine größeren oder gar bedenklichen Gebrauchsspuren.",
    ["What is Anseilak, and how do I give them that?"] = "Was ist Anseilak und wie schenke ich es ihnen?",
    ["All right. I'll help you perform Anseilak for the Yokudan mages."] = "In Ordnung. Ich helfe Euch dabei, Anseilak für die yokudanischen Magier durchzuführen.",
    ["No. What're you on pilgrimage for?"] = "Nein. Warum unternehmt Ihr eine Pilgerreise?",
    ["Withered Water Skin"] = "verwitterter Trinkschlauch^m",
    ["If only I could survive the journey. Every New Life, we give Anseilak to the fallen Yokudans so that their spirits may rest peacefully. However, Yokudan mages are ignored for their involvement in magic.\n\nTraveler. Will you give them Anseilak?"] = "Wenn ich die Reise doch nur überlebte. Jedes Neujahrsfest schenken wir den gefallenen Yokudanern Anseilak, damit ihre Geister in Frieden ruhen können. Yokudanische Magier werden jedoch ignoriert, da sie sich mit Magie eingelassen haben.\n\n<<player{Reisender/Reisende}>>. Würdet Ihr ihnen Anseilak schenken?",
    ["Forgive me. It is a ritual where we gather seawater that once touched Yokuda's lands. We then perform it for the fallen mages resting at Motalion Necropolis, bringing them peace.\n\nKnow your efforts will be repaid in full."] = "Verzeiht mir. Das ist ein Ritual, bei dem wir Meerwasser beschaffen, das einst Yokudas Lande berührte. Dann führen wir es für die gefallenen Magier durch, die in der Nekropole Motalion ruhen, damit sie Frieden finden.\n\nWisset, dass Eure Mühen vergütet werden.",
    ["I must bring peace to the rest of the Yokudans."] = "Ich muss den anderen Yokudanern Frieden bringen.",
    ["Water that once touched the ancient land of Yokuda, now sunken deep beneath the sea."] = "Wasser, das einst die uralten Lande von Yokuda berührte und nun tief in die See hinabsank.",
    ["Fresh Seawater"] = "frisches Meerwasser^ns",
    ["You prepared a hearty, rich baked potato for Nenilon. Deliver it to him near the banks of Toothmaul Gully as an offering for New Life."] = "Ihr habt eine herzhafte und reichhaltige Ofenkartoffel für Nenilon zubereitet. Bringt sie ihm bei den Ufern der Zahnbrecherrinne als Neujahrsgabe.",
    ["I learned that Lanullin is leading an effort to give back to esteemed High Elf elders in her community. However, it seems they're shorthanded. I agreed to help her however I can."] = "Ich erfuhr, dass Lanullin ein Vorhaben leitet, das dazu dient, den geschätzten Hochelfenältesten ihrer Gemeinschaft etwas zurückzugeben. Allerdings herrscht anscheinend Personalnot. Ich willigte ein, ihr zu helfen, wie ich nur kann.",
    ["Giving back? How?"] = "Etwas zurückgeben? Wie das?",
    ["All right. I'll help Lanullin in Auridon."] = "In Ordnung. Ich helfe Lanullin in Auridon.",
    ["I'm interested. Tell me more."] = "Ich bin interessiert. Erzählt mir mehr darüber.",
    ["Nenilon's Baked Potato Offering"] = "Nenilons Ofenkartoffel^Fg",
    ["Here's a New Life festivity that strikes a chord in me. Lanullin leads an earnest effort to give back to High Elf elders this season, especially those who shared their wisdom with her community."] = "Es gibt eine Neujahrstradition, die eine Saite in meinem Herzen zum Klingen bringt. Lanullin bemüht sich redlich, den Ältesten der Hochelfen in dieser Zeit etwas zurückzugeben, besonders jenen, die ihre Weisheit mit der Gemeinschaft teilten.",
    ["By rattling pots and pans and cooking up something delicious! A shame, though. I hear she doesn't have enough help to make offerings for all the elders she hopes to provide for.\n\nCould you lend them a hand in Auridon, friend?"] = "Indem sie mit Töpfen und Pfannen klappert und etwas Leckeres kocht! Schade allerdings, dass sie nicht genug Hilfe hat, um für alle Ältesten, die sie versorgen möchte, Gaben zuzubereiten.\n\nKönntet Ihr ihr in Auridon dabei helfen, <<player{mein Freund/meine Freundin}>>?",
    ["Help support Auridon's elders for New Life!"] = "Helft, die Ältesten Auridons zum Neujahr zu unterstützen!",
    ["You prepared a sweet and tempting banana surprise for Geraldrim. Deliver it to him near the Ezduiin's Ruins as an offering for New Life."] = "Ihr habt eine süße und verlockende Bananenüberraschung für Geraldrim zubereitet. Bringt sie ihm zu den Ruinen von Ezduiin als Neujahrsgabe.",
    ["A wealthy Khajiit seems to be hosting a game for New Life that involves hoards of gold and a grand opponent guarding it. To learn more, I need to speak to Tibarr, the organizer for this festivity."] = "Ein reicher Khajiit scheint ein Spiel zum Neujahr anzubieten, bei dem es um gehortetes Gold und mächtige Gegner geht, die diesen Schatz bewachen. Um mehr zu erfahren, muss ich mit Tibarr sprechen, dem Ausrichter der Feierlichkeiten.",
    ["Tell me about this guardian."] = "Erzählt mir von diesem Wächter.",
    ["All right. I'll speak to Tibarr in Rawl'kha."] = "In Ordnung. Ich spreche mit Tibarr in Knurr'kha.",
    ["Geraldrim's Banana Surprise Offering"] = "Geraldrims Bananenüberraschung^Fg",
    ["I hesitate to mention due to the danger, but you seem the daring sort. A wealthy Khajiit in Rawl'kha has put a hoard of gold on the line—if you can overcome its guardian."] = "Ob der Gefahr zögere ich, es zu erwähnen, doch Ihr wirkt wagemutig. Ein reicher Khajiit in Knurr'kha hat einen Hort von Gold aufgeboten – wenn Ihr dessen Wächter überwinden könnt.",
    ["New Life is about surprises, too, my friend! I'll let Tibarr be the one to reveal his grand scheme to you.\n\nBut a word of caution—watch your step when you face the guardian!"] = "Beim Neujahr geht es auch um Überraschungen, <<player{mein Freund/meine Freundin}>>! Ich werde es Tibarr überlassen, Euch seine großen Pläne zu enthüllen.\n\nDoch ein Wort der Warnung: Achtet darauf, wo Ihr hintretet, wenn Ihr dem Wächter gegenübersteht!",
    ["Here's a New Life festivity for those who love a challenge!"] = "Eine Neujahrstradition für alle, die Herausforderungen lieben!",
    ["You prepared a warm, nourishing carrot soup for Teliwe. Deliver it to her at the College of Aldmeri as an offering for New Life."] = "Ihr habt eine warme, nahrhafte Karottensuppe für Teliwe zubereitet. Bringt sie ihr zum Kolleg der aldmerischen Schicklichkeit als Neujahrsgabe.",
    ["Anicus mentioned an angler called Yesei trying to catch a fabled Dakoi fish for New Life. He thinks he needs help, and that I should speak to him."] = "Anicus erwähnte einen Angler namens Yesei, der versucht, einen sagenumwobenen Dakoi-Fisch für das Neujahrsfest zu fangen. Er meint, der Angler brauche Hilfe und ich solle mit ihm sprechen.",
    ["Interesting. Tell me more."] = "Ich bin interessiert. Erzählt mir mehr darüber.",
    ["All right. I'll find Yesei in Stormhold."] = "In Ordnung. Ich suche Yesei in Sturmfeste auf.",
    ["Teliwe's Carrot Soup Offering"] = "Teliwes Karottensuppe^Fg",
    ["Let me tell you about the murky waters of Stormhold. Nearly fell in when a poor angler rushed past me in pursuit of the fabled Dakoi fish.\n\nIt's a strange way to celebrate New Life, but that's what makes it special!"] = "Lasst mich Euch von den trüben Gewässern von Sturmfeste erzählen. Einmal bin ich fast hineingefallen, als ein armer Angler auf der Jagd nach dem sagenumwobenen Dakoi-Fisch an mir vorbeihetzte.\n\nEs ist eine seltsame Art, das Neujahrsfest zu feiern, aber das macht es so besonders!",
    ["The Dakoi only appears during the New Life season. Poor Yesei has been chasing it all over Stormhold. Whoever catches it gets a year of good luck, and Yesei could really use some.\n\nIf you don't mind getting a little wet, go help him out!"] = "Der Dakoi erscheint nur während des Neujahrs. Der arme Yesei hat ihn durch ganz Sturmfeste gejagt. Wer ihn fängt, hat ein Jahr lang Glück, und das könnte Yesei wirklich gebrauchen.\n\nWenn Ihr kein Problem habt, Euch nass zu machen, geht und helft ihm!",
    ["Will you be the one to hook Stormhold's fabled Dakoi this season?"] = "Werdet Ihr dieses Jahr den sagenumwobenen Dakoi von Sturmfeste an den Haken kriegen?",
    ["Prepare carrot soup and deliver it to Teliwe at the College of Aldmeri as an offering for New Life."] = "Bereitet eine Karottensuppe zu und bringt sie Teliwe ins Kolleg der aldmerischen Schicklichkeit als Neujahrsgabe.",
    ["In Elden Root, Dailonda and her followers are constructing a Mudman effigy to bless Tamriel, but they need a hand. I agreed to help her however I can."] = "In Eldenwurz errichten Dailonda und ihre Anhänger ein Schlammkerl-Abbild, um Tamriel zu segnen, doch sie brauchen Hilfe. Ich willigte ein, ihr so gut zu helfen, wie ich kann.",
    ["Mudman effigy? She's sculpting with mud?"] = "Schlammkerl-Abbild? Sie formt es aus Schlamm?",
    ["I'll head to Elden Root and help Dailonda."] = "Ich reise nach Eldenwurz und helfe Dailonda.",
    ["This one's a bit messy. Dailonda's kin usually help her with the sculpting for New Life, but they all recently departed Elden Root's branches for newer trees.\n\nNow, it's only her, a few of her followers, and their Mudman effigy."] = "Bei dem hier wird es etwas dreckiger. Dailondas Familie hilft ihr üblicherweise mit dem Formen für Neujahr, aber sie alle haben die Äste von Eldenwurz vor Kurzem in Richtung neuerer Bäume verlassen.\n\nJetzt ist sie allein, mit einigen ihrer Begleiter und ihrem Schlammkerl-Abbild.",
    ["Like I said, messy. When completed, the Mudman bestows its blessing upon Tamriel. But poor Dailonda also believes that bad luck follows if the sculpture isn't finished.\n\nSo, are you up for frolicking in the mud and lending a hand?"] = "Wie ich sagte: dreckig. Sobald er vollendet ist, spendet der Schlammkerl Tamriel seinen Segen. Doch die arme Dailonda glaubt auch, es bringe Unglück, wenn er unvollendet bleibt.\n\nNun, seid Ihr bereit, im Schlamm zu tollen und ihr zur Hand zu gehen?",
    ["Who doesn't mind a little dirt for a New Life blessing?"] = "Wer nimmt nicht ein bisschen Schmutz in Kauf für einen Neujahrssegen?",
    ["Prepare a baked potato and deliver it to Nenilon near the banks of Toothmaul Gully as an offering for New Life."] = "Bereitete ein Ofenkartoffel vor und bringt sie Nenilon bei den Ufern der Zahnbrecherrinne als Neujahrsgabe.",
    ["I learned that a group of Orcs in Betnikh celebrate New Life by breaking boulders for a special boon. To participate, I need to speak to Mahagog, their leader."] = "Ich erfuhr, dass eine Gruppe Orks in Betnikh das Neujahrsfest feiert, indem sie Felsen für einen besonderen Segen zerschmettert. Um mitzumachen, muss ich mit ihrem Anführer Mahagog sprechen.",
    ["What's Betnikh's Boon?"] = "Was ist Betnikhs Segen?",
    ["All right. I'll talk to Mahagog at Stonetooth Fortress."] = "Nun gut. Ich spreche an der Steinzahn-Festung mit Mahagog.",
    ["Orcs over in Betnikh compete for Betnikh's Boon in a contest of strength every New Life. The competition involves physical strength, keen reflexes, and huge boulders!"] = "Drüben in Betnikh messen sich Orks jedes Neujahr in einem Stärke-Wettbewerb, um Betnikhs Segen zu erhalten. Dabei dreht sich alles um körperliche Kraft, schnelle Reflexe und riesige Felsbrocken!",
    ["A favor or benefit of some kind. You'd have to ask Mahagog. He's leading the contest. You can find him at Stonetooth Fortress in Betnikh.\n\nFair warning—he loves competition and hates to lose."] = "Ein Gefallen oder Vorzug irgendeiner Art. Das müsstet Ihr Mahagog fragen. Er leitet den Wettbewerb. Ihr findet ihn an der Steinzahn-Festung in Betnikh.\n\nEin Wort der Warnung: Er liebt Wettbewerbe und ist ein schlechter Verlierer.",
    ["If you've got muscles, I've got a New Life festivity for you!"] = "Wenn Ihr Muskeln habt, hätte ich eine Neujahrstradition für Euch!",
    ["Prepare a banana surprise and deliver it to Geraldrim near the Ezduiin's Ruins as an offering for New Life."] = "Bereitet eine Bananenüberraschung vor und bringt sie Geraldrim bei den Ruinen von Ezduiin als Neujahrsgabe.",
    ["A lone traveler seems to be asking for help making a pilgrimage. Supposedly, it can help bring peace to the fallen Yokudans during New Life. I agreed to help however I can."] = "Jemand, der gerade eine einsame Reise unternimmt, scheint um Hilfe bei seiner Pilgerfahrt zu bitten. Angeblich will diese Person während Neujahr gefallenen Yokudanern Frieden bringen. Ich willigte ein, ihr so gut zu helfen, wie ich kann.",
    ["Any reason why nobody wants to help them?"] = "Gibt es einen Grund, warum niemand Hilfe anbieten will?",
    ["All right. I'll find them in Sentinel."] = "In Ordnung. Ich suche in Schildwacht nach dieser Person.",
    ["This one I haven't been able to check personally. Whispers carried by Sentinel's winds tell of a lone traveler seeking help from passersby for New Life. Something about a pilgrimage to bring fallen Yokudans peace.\n\nAlas, the pleas fall on deaf ears."] = "Das hier konnte ich mir nicht persönlich ansehen. Schildwachts Winde flüstern von jemandem, der gerade auf einer einsamen Reise ist und zu Neujahr Hilfe von Vorübergehenden erbittet. Diese Person spricht von einer Pilgerfahrt, um gefallenen Yokudanern Frieden zu bringen.\n\nLeider stoßen ihre Bitten auf taube Ohren.",
    ["Who can say? I hear Redguard have peculiar notions regarding the dead, so perhaps that's part of it.\n\nIf you can deal with hot sand and biting winds, seek them out in Sentinel. It would be a shame if their approach to New Life didn't succeed."] = "Wer weiß? Rothwardonen sollen sonderbare Vorstellungen über die Toten haben. Vielleicht gehört das dazu.\n\nWenn Ihr den heißen Sand und beißende Winde ertragen könnt, macht Euch in Schildwacht auf die Suche nach dieser Person. Es wäre eine Schande, wenn diese Neujahrsbemühungen keinen Erfolg fänden.",
    ["New Life and long dead in Sentinel! Ask me for details!"] = "Neues Jahr und alte Tote in Schildwacht! Fragt mich gern nach Einzelheiten!",
    ["Many Nords seem to describe a hermit claiming that his pet bear's mood is important this New Life. I should speak to him to learn more about what he needs."] = "Viele Nord erwähnen einen Einsiedler, der behauptet, die Laune seines zahmen Bären sei zum Neujahrsfest wichtig. Ich sollte mit ihm sprechen, um mehr darüber zu erfahren, wie ich helfen kann.",
    ["His bear?"] = "Sein Bär?",
    ["All right. I'll head to the Rift and talk to the hermit."] = "In Ordnung. Ich reise nach Rift und spreche mit dem Einsiedler.",
    ["Here's a bizarre one I haven't had a chance to check on yet. A crazed hermit in the Rift proclaims this will be the last New Life. That the end of days are upon us. Heh, what else is new?\n\nBut here's the twist—his bear is the problem."] = "Hier ist etwas Absonderliches, was ich noch nicht überprüfen konnte: Ein verrückter Einsiedler in Rift verkündet, dies werde das letzte Neujahr sein. Dass das Ende aller Tage bevorstünde. Ha, was gibt es sonst noch Neues?\n\nDoch hier kommt die unerwartete Wendung: Es liegt alles an seinem Bären.",
    ["Pet bear, yes. Seems like the bear's mood determines the fate of each New Life, and right now the bear is miserable. The hermit needs help cheering him up.\n\nThe bear's also … quite large. Hard to miss. Find them by a lake near Skald's Retreat."] = "Sein Hausbär, ja. Die Laune des Bären scheint über das Schicksal für jedes Neujahr zu bestimmen, und gerade geht es ihm schrecklich. Der Einsiedler braucht Hilfe, um ihn aufzuheitern.\n\nDer Bär ist noch dazu ... recht groß. Kaum zu übersehen. Ihr findet die beiden an einem See unweit der Skaldenzuflucht.",
    ["Hermit claims this may be Tamriel's last New Life! Talk to me to learn more!"] = "Einsiedler behauptet, dies könnte das letzte Neujahr sein! Sprecht mich an, wenn Ihr mehr erfahren wollt!",
    ["An empty bottle of bloodwine that still has a strong scent to it."] = "Eine leere Flasche Blutwein, die immer noch kräftig nach ihrem ehemaligen Inhalt riecht.",
    ["I met Jahesi once again out in Sentinel. It seems she'd like to continue performing Anseilak for the fallen Yokudan mages until New Life's end. I agreed to travel with her and help with the ritual."] = "Ich begegnete draußen in Schildwacht Jahesi wieder. Anscheinend würde sie gern bis zum Ende des Neujahrfests weiter das Ritual namens Anseilak für gefallene yokudanische Magier durchführen. Ich willigte ein, mit ihr zu reisen und ihr bei dem Ritual zu helfen.",
    ["And you're going to do this every day?"] = "Und das werdet Ihr jeden Tag tun?",
    ["All right. Let's perform Anseilak."] = "In Ordnung. Führen wir also Anseilak durch.",
    ["Do you need help with something?"] = "Könnt Ihr ein wenig Hilfe gebrauchen?",
    ["Bottle of Bloodwine"] = "Flasche Blutwein^f",
    ["I need to perform Anseilak for the other Yokudan mages, but my blessing alone won't be enough to make up for the centuries they've been shunned. And most Redguard scowl when I mention them."] = "Ich muss Anseilak für die anderen yokudanischen Magier durchführen, aber meine Segnungen allein werden die Jahrhunderte nicht wettmachen, die sie ignoriert wurden. Und die meisten Rothwardonen legen die Stirn in Falten, wenn ich sie erwähne.",
    ["Until New Life's end. You certainly don't have to trudge through the sand with me every day. But having another blessing would help the mages. And me.\n\nRest assured I'll reward you for your time."] = "Bis das Neujahrsfest endet. Ihr müsst aber nicht jeden Tag mit mir durch den Sand stapfen. Ein weiterer Segen würde den Magiern schon weiterhelfen. Und mir.\n\nIch werde Euch auch für Eure Zeit entlohnen. Dessen könnt Ihr Euch sicher sein.",
    ["Alik'r's winds have reunited us once more, traveler."] = "Die Winde von Alik'r führen uns einmal mehr zusammen, <<player{Reisender/Reisende}>>.",
    ["A wet, earthy clump of mud. Caught and reeled from Shadowfen's fishing holes."] = "Ein feuchter, erdiger Klumpen Schlamm. Gefangen und eingeholt in den Fischgründen von Schattenfenn.",
    ["Clump of Mud"] = "Schlammklumpen^m",
    ["Shriveled fish scales. Probably the leftovers of a predator's meal."] = "Vertrocknete Fischschuppen. Wahrscheinlich das, was ein Raubtier von seiner Mahlzeit übrig ließ.",
    ["Bundle of Fish Scales"] = "Fischschuppenbündel^n",
    ["I don't know what the Worm Cult wants with the Staff of Magnus or Prince Naemon, but it sounds disastrous. Queen Ayrenn, the Dominion, everything is in jeopardy.\n \nI have the beginnings of a plan, but I can't move fast enough with this injury."] = "Ich weiß nicht, was der Wurmkult mit dem Stab des Magnus oder mit Prinz Naemon vorhat, aber es klingt verheerend. Königin Ayrenn, das Dominion, alles ist in Gefahr.\n\nIch habe erste Ansätze eines Plans, aber mit dieser Wunde bin ich einfach zu langsam.",
    ["A Trick to the Doors"] = "Der Kniff mit den Türen^N",
    ["What does it hurt to spin some yarn about me dying like a hero? I just want her to remember me with fondness, that's all.\n\nI'm sure she'll pay you for your delivering the news. She has a good heart. Please. Above all else, she needs to know."] = "Wem schadet es, wenn Ihr Euch eine Geschichte ausdenkt, in der ich wie ein Held sterbe? Ich will nur, dass man sich mit Zuneigung an mich erinnert, mehr nicht.\n\nIch bin sicher, dass sie Euch für diese Nachricht belohnen wird. Sie hat ein gutes Herz. Bitte. Vor allem muss sie es erfahren.",
    ["A carelessly dropped note written by Terinvel. Sirilonwe wants to see it."] = "Eine achtlos fallengelassene Notiz von Terinvel. Sirilonwe möchte sie sehen.",
    ["Glenumbra"] = "Glenumbra^N",
}